export type ClockLine = {
  /**
   * Clock rate in substitutions per site per year.
   */
  rate: number;
  /**
   * Divergence at year 0.
   */
  intercept: number;
};

/**
 * The tree of a draft, as the preview draws it.
 */
export type PreviewTree = {
  /**
   * Where the root of the tree comes from.
   */
  root: PreviewRoot;
  /**
   * The tree as an Auspice document, with the divergence of every node and no dates.
   */
  auspice: AuspiceDocument;
};

/**
 * Where the root of a preview tree comes from.
 */
export type PreviewRoot = 'regression' | 'input';

/**
 * Auspice JSON of a run, with the color scales the app displays.
 */
export type AuspiceDocument = {
  [key: string]: unknown;
};

/**
 * Runs, newest first, and the number of runs computing now.
 */
export type RunList = {
  /**
   * Runs, newest first.
   */
  runs: Array<RunSummary>;
  /**
   * Number of runs whose computation is running now. Every run shares one pool of processing threads.
   */
  active_runs: number;
};

/**
 * Entry of a run list.
 */
export type RunSummary = {
  /**
   * Identifier of the run.
   */
  id: JobId;
  /**
   * Title of the run.
   */
  title: string;
  /**
   * Command the run executes.
   */
  command: AppCommand;
  /**
   * State of the run.
   */
  status: RunStatus;
  /**
   * Whether the run is pinned.
   */
  pinned: boolean;
  /**
   * Run whose settings this run started from. The source may have been deleted since.
   */
  source_run_id?: JobId;
  /**
   * Group of related runs in the run history.
   */
  group_id: JobId;
  /**
   * Size of the run in bytes: its output files and the uploaded inputs that no other run references.
   */
  size: number;
  /**
   * Time the run was created.
   */
  created_at: string;
  /**
   * Time the run ended.
   */
  finished_at?: string;
  /**
   * Duration of the computation, in seconds.
   */
  duration_seconds?: number;
  /**
   * Hash that identifies runs with the same settings and input contents.
   */
  config_hash?: string;
  /**
   * Setting keys whose values differ from the command defaults.
   */
  changed_settings: Array<string>;
  /**
   * Key results of a finished run.
   */
  headline: RunHeadline;
  /**
   * Name to save the run package under: the run's title and the start of its id, as in the names of its output
   * files, for example `ebola-100-time-tree-1a2b3c4d.zip`.
   */
  package_name: string;
};

/**
 * State of a run.
 */
export type RunStatus = 'created' | 'running' | 'ok' | 'error' | 'cancelled' | 'interrupted';

/**
 * Key results of a finished run, for run lists; the same values the run's results show.
 */
export type RunHeadline = {
  /**
   * Date of the root: of the time tree, or where the root-to-tip regression of a clock run reaches zero divergence.
   */
  root_date?: YearDate;
  /**
   * Clock rate in substitutions per site per year.
   */
  clock_rate?: JsonFloat;
  /**
   * Coefficient of determination of the clock model.
   */
  r_squared?: JsonFloat;
  /**
   * Number of distinct substitutions on two or more branches of a homoplasy run.
   */
  recurrent_substitutions?: number;
};

/**
 * A number; infinities and NaN are the strings "inf", "-inf" and "nan".
 */
export type JsonFloat = number | 'inf' | '-inf' | 'nan';

/**
 * Request to create a run.
 */
export type CreateRunRequest = {
  /**
   * Command the run executes.
   */
  command: AppCommand;
  /**
   * Configuration of the command, in the form `treetime <command> --config` reads. A configuration that the command
   * rejects is answered with an `invalid_request` error.
   */
  config: SparseConfig;
  /**
   * Whether to wait for an explicit start instead of starting at once, for example to upload inputs first.
   */
  defer_start?: boolean;
  /**
   * Run whose settings the new run starts from, such as the source of a variant.
   */
  source_run_id?: JobId;
  /**
   * Name of the example dataset whose files the run reads, for example `ebola/100`; unset for the user's own files.
   * The run's name starts with it.
   */
  example?: string;
};

/**
 * Durable record of one command run, stored as `run.json` in the run's folder. Every path in the record that lies in
 * the run's folder or in the store of uploaded inputs is relative to the run's folder: uploads appear as
 * `inputs/<name>`, or `inputs/<n>/<name>` when two different uploads share a name, and outputs below `out/`. Inputs
 * read from elsewhere keep their absolute paths.
 */
export type RunRecord = ({
  command: 'timetree';
} & RunRecordTimetree) | ({
  command: 'optimize';
} & RunRecordOptimize) | ({
  command: 'prune';
} & RunRecordPrune) | ({
  command: 'ancestral';
} & RunRecordAncestral) | ({
  command: 'clock';
} & RunRecordClock);

/**
 * One input file of a run.
 */
export type RunInput = {
  /**
   * Dot-separated key path of the setting that names the file.
   */
  setting: string;
  /**
   * Path of the file: `inputs/<name>` or `inputs/<n>/<name>` relative to the run's folder for an uploaded file;
   * `inputs/<setting>/...` for a file that a path template of an imported run names, kept in the run's folder; the
   * absolute path for a file read from elsewhere.
   */
  path: string;
  /**
   * Size of the file in bytes.
   */
  size: number;
  /**
   * SHA-256 of the file contents, as lowercase hexadecimal.
   */
  sha256: string;
};

/**
 * Key of a file in the input store: the SHA-256 of its contents and its file name.
 */
export type StoredInput = {
  /**
   * SHA-256 of the file contents, as lowercase hexadecimal.
   */
  sha256: string;
  /**
   * File name of the upload.
   */
  name: string;
};

/**
 * One file a command wrote.
 */
export type OutputFile = {
  /**
   * Path of the file.
   */
  path: string;
  /**
   * Output selection that produced the file.
   */
  kind: OutputSelection;
  /**
   * Alignment file the output belongs to, for an output written once per alignment file.
   */
  alignment?: OutputAlignment;
};

/**
 * Canonical lookup key for selectable outputs. Command adapters convert their
 * selection enums into this type, and [`plan`] resolves each key to a path.
 * Tree variants do not encode the separately selected Newick annotations.
 */
export type OutputSelection = 'all' | 'nwk' | 'nexus' | 'auspice' | 'mat-pb' | 'mat-json' | 'graph-json' | 'dot' | 'node-data' | 'model' | 'clock-model' | 'dates' | 'trait-probabilities' | 'sequences' | 'translations' | 'traits' | 'rtt' | 'tracelog' | 'coalescent' | 'coalescent-json' | 'rtt-chart' | 'homoplasy-stats' | 'homoplasy-report';

/**
 * The alignment file of an output written once per alignment file.
 */
export type OutputAlignment = {
  /**
   * Alignment number: the position of the file in the alignment setting, starting at 1.
   */
  number: number;
  /**
   * Path of the alignment file.
   */
  path: string;
};

/**
 * A problem that the run found and continued past, which makes its results less reliable.
 */
export type RunWarning = {
  /**
   * Kind of the problem.
   */
  kind: RunWarningKind;
  /**
   * The problem, as a sentence; the run log shows the same text.
   */
  message: string;
  /**
   * Every name the problem concerns, sorted; an edge is named by its child node. The message may show only some of them.
   */
  names: Array<string>;
};

/**
 * Kind of a run warning.
 */
export type RunWarningKind = 'duplicate-node-names' | 'duplicate-sequence-names' | 'duplicate-metadata-names' | 'duplicate-partition-names' | 'branch-lengths-not-converged' | 'dates-outside-input-dates' | 'filtered-tips-removed' | 'undated-tips-removed' | 'locations-without-coordinates';

/**
 * Error of a failed run.
 */
export type RunError = {
  /**
   * The error, as the CLI prints it.
   */
  message: string;
  /**
   * The errors that caused `message`, outermost first.
   */
  causes: Array<string>;
  /**
   * Keys of the settings whose command-line flags the error and its causes name, in the order they name them.
   */
  settings: Array<string>;
};

/**
 * Changes to the presentation of a run.
 */
export type UpdateRunRequest = {
  /**
   * New title.
   */
  title?: string;
  /**
   * New pinned state.
   */
  pinned?: boolean;
};

/**
 * Request to start a created run.
 */
export type StartRunRequest = {
  /**
   * Command that replaces the one given at creation, for example when the user chose another analysis after
   * uploading its inputs.
   */
  command?: AppCommand;
  /**
   * Configuration that replaces the one given at creation, for example to point at uploaded inputs.
   */
  config?: SparseConfig;
  /**
   * Run whose settings the run starts from; replaces the one given at creation.
   */
  source_run_id?: JobId;
  /**
   * Name of the example dataset whose files the run reads, for example `ebola/100`; replaces the one given at
   * creation, for example when the user opened an example after the run that holds the uploads was created. The run's
   * name starts with it.
   */
  example?: string;
};

/**
 * Answer to a cancellation request.
 */
export type CancelRunResponse = {
  /**
   * Whether cancellation was requested; the run ends with a `cancelled` terminal event.
   */
  cancelled: boolean;
};

/**
 * One file in a run's `out/` folder.
 */
export type RunFile = {
  /**
   * Path relative to the run's `out/` folder, with `/` separators.
   */
  path: string;
  /**
   * Name to save the file under: the run's title, the start of its id, and the path, so that the files of different
   * runs do not share a name, for example `ebola-100-time-tree-1a2b3c4d.timetree.nwk`.
   */
  download_name: string;
  /**
   * Short name of the file with its format, for example `Dated tree (Newick, branch lengths in years)`; the file name
   * for files the output plan does not name.
   */
  label: string;
  /**
   * Size in bytes.
   */
  size: number;
  /**
   * Output selection that produced the file; absent for files the output plan does not name.
   */
  kind?: OutputSelection;
  /**
   * What the file holds; empty for files the output plan does not name.
   */
  description: string;
  /**
   * Whether the file is one of the main formats of the command, which the Download menu offers. The list holds these
   * files first, in menu order, then the other files by path.
   */
  main: boolean;
  /**
   * Alignment file the output belongs to, for an output written once per alignment file.
   */
  alignment?: OutputAlignment;
};

/**
 * Results of a finished run, read from its output files.
 */
export type RunResults = {
  /**
   * Tree of the run's Auspice file; absent when the run wrote none.
   */
  tree?: ResultTree;
  /**
   * Alignment file whose Auspice file gives the tree, when the run has several alignment files.
   */
  tree_alignment?: OutputAlignment;
  /**
   * Substitution models and alignment files of the run's model document; empty when the run wrote none.
   */
  models: RunModels;
  /**
   * Results specific to the command of the run.
   */
  results: CommandResults;
  /**
   * The publication to cite.
   */
  citation: Citation;
  /**
   * Output files, and the input tree of an `optimize` or `prune` run, that could not be read.
   */
  problems: Array<OutputProblem>;
};

/**
 * A tree a run wrote, read from its Auspice file.
 */
export type ResultTree = {
  /**
   * Nodes in preorder; the root comes first and every parent precedes its children.
   */
  nodes: Array<ResultNode>;
  /**
   * Colorings the Auspice file offers.
   */
  colorings: Array<ResultColoring>;
  /**
   * Coloring the Auspice file selects by default.
   */
  default_color_by?: string;
};

/**
 * One node of a result tree.
 */
export type ResultNode = {
  /**
   * Name of the node.
   */
  name: string;
  /**
   * Index of the parent node; absent for the root.
   */
  parent?: number;
  /**
   * Indices of the child nodes.
   */
  children: Array<number>;
  /**
   * Number of samples below the node, 1 for a sample.
   */
  tips: number;
  /**
   * Divergence from the root.
   */
  div?: number;
  /**
   * Date of the node.
   */
  date?: YearDate;
  /**
   * Confidence interval of the date; absent when the run computed none or the interval is empty.
   */
  date_interval?: DateInterval;
  /**
   * Whether the clock model left the sample out, because it had no usable date or was a clock outlier.
   */
  excluded?: boolean;
  /**
   * Nucleotide mutations on the branch above the node.
   */
  mutations: Array<string>;
};

/**
 * Confidence interval of a date.
 */
export type DateInterval = {
  /**
   * Earliest date.
   */
  lower: YearDate;
  /**
   * Latest date.
   */
  upper: YearDate;
  /**
   * Width of the interval in days.
   */
  days: number;
  /**
   * Probability that the date lies inside the interval, for example `0.9`.
   */
  level: number;
};

/**
 * A coloring of the Auspice tree.
 */
export type ResultColoring = {
  /**
   * Node attribute the coloring reads.
   */
  key: string;
  /**
   * Title of the coloring.
   */
  title: string;
  /**
   * Kind of scale, for example `categorical` or `continuous`.
   */
  kind: string;
  /**
   * Distinct states of a categorical coloring, sorted; empty for other kinds.
   */
  states: Array<string>;
};

/**
 * The substitution models of a run, from its model document.
 */
export type RunModels = {
  /**
   * Alignment files of the run, in the order of the `--alignment` list; empty for runs without alignments.
   */
  alignments: Array<AlignmentSummary>;
  /**
   * Models in the order of the model document: one per partition, or one per trait.
   */
  models: Array<RunModel>;
};

/**
 * One alignment file of a run.
 */
export type AlignmentSummary = {
  /**
   * Alignment number: the position of the file in the `--alignment` list, starting at 1.
   */
  alignment: number;
  /**
   * Path of the alignment file.
   */
  path: string;
  /**
   * Number of sites of the alignment file.
   */
  sites: number;
  /**
   * Rate of insertion and deletion events per unit of branch length in this file; absent when the run has no indel term.
   */
  indel_rate?: number;
};

/**
 * A substitution model of a run, from its model document.
 */
export type RunModel = ({
  kind: 'sequence';
} & RunModelSequence) | ({
  kind: 'trait';
} & RunModelTrait);

/**
 * The substitution model fitted to one partition.
 */
export type SequenceModelSummary = {
  /**
   * Partition number, starting at 1, in the order of the model document.
   */
  partition: number;
  /**
   * Name of the partition entry; absent for partitions without a name.
   */
  name?: string;
  /**
   * Number of the alignment file of the partition.
   */
  alignment: number;
  /**
   * Path of the alignment file of the partition; absent when the model document does not list the file.
   */
  path?: string;
  /**
   * Number of sites of the partition.
   */
  sites: number;
  /**
   * Name of the model.
   */
  model: string;
  /**
   * Overall substitution rate.
   */
  mu: number;
  /**
   * Characters of the states in the order of the rows and columns of `W` and the entries of `pi` in the model document.
   */
  states: Array<string>;
  /**
   * Equilibrium frequencies of the states, in the order of `states`.
   */
  pi: Array<number>;
  /**
   * Substitution rates between the states per unit of branch length: `rates[a][b]` is the rate from state `a` to
   * state `b`, `mu * pi[b] * W[a][b]`, with zeros on the diagonal.
   */
  rates: Array<Array<number>>;
};

/**
 * The substitution model fitted to the states of one discrete trait.
 */
export type TraitModelSummary = {
  /**
   * Metadata column of the trait.
   */
  attribute: string;
  /**
   * Name of the model.
   */
  model: string;
  /**
   * Overall substitution rate.
   */
  mu: number;
  /**
   * Trait states in the order of the rows and columns of `W` and the entries of `pi` in the model document.
   */
  states: Array<string>;
  /**
   * Equilibrium frequencies of the states, in the order of `states`.
   */
  pi: Array<number>;
  /**
   * Substitution rates between the states per unit of branch length: `rates[a][b]` is the rate from state `a` to
   * state `b`, `mu * pi[b] * W[a][b]`, with zeros on the diagonal.
   */
  rates: Array<Array<number>>;
};

/**
 * Results specific to the command of a run.
 */
export type CommandResults = ({
  command: 'timetree';
} & CommandResultsTimetree) | ({
  command: 'clock';
} & CommandResultsClock) | ({
  command: 'ancestral';
} & CommandResultsAncestral) | ({
  command: 'optimize';
} & CommandResultsOptimize) | ({
  command: 'prune';
} & CommandResultsPrune);

/**
 * Results of a `timetree` run.
 */
export type TimetreeResults = {
  /**
   * Estimates of the time tree; absent when the run wrote no Auspice tree.
   */
  estimates?: TimetreeEstimates;
  /**
   * Statistics of the root-to-tip regression of the final clock model in display order; empty when the run wrote no
   * clock model.
   */
  statistics: Array<RegressionStatistic>;
  /**
   * Samples and line of the final clock model; absent when the run wrote no clock regression table.
   */
  root_to_tip?: RootToTip;
  /**
   * Convergence values of every iteration, from the tracelog.
   */
  iterations: Array<IterationRow>;
  /**
   * Segments of the coalescent time scale, from the coalescent table.
   */
  skyline: Array<SkylineSegment>;
};

/**
 * Estimates of a `timetree` run.
 */
export type TimetreeEstimates = {
  /**
   * Date of the root.
   */
  root_date?: YearDate;
  /**
   * Confidence interval of the root date.
   */
  root_interval?: DateInterval;
  /**
   * Whether the root date lies within 5% of the interval width from a bound of its interval.
   */
  root_near_interval_edge: boolean;
  /**
   * Clock rate in substitutions per site per year.
   */
  clock_rate?: number;
  /**
   * Standard deviation of the clock rate: the estimate's, or the one given with a fixed rate.
   */
  clock_rate_std?: number;
  /**
   * Whether the clock rate was fixed by the user instead of estimated.
   */
  clock_rate_fixed: boolean;
  /**
   * Correlation coefficient of the final clock model; absent for a fixed rate.
   */
  r?: number;
  /**
   * Coefficient of determination of the final clock model.
   */
  r_squared?: number;
  /**
   * Number of samples in the tree.
   */
  samples: number;
  /**
   * Date of the latest sample that the clock model kept.
   */
  latest_sample?: YearDate;
  /**
   * Number of samples the clock model left out: without a usable date or clock outliers.
   */
  excluded_samples: number;
  /**
   * Coalescent prior the run used.
   */
  coalescent_prior: CoalescentPrior;
  /**
   * Relaxed clock the run used.
   */
  relaxed_clock?: RelaxedClock;
  /**
   * Log marginal likelihood of the node times in the last iteration (the iterations' `log_lh_time`).
   */
  log_likelihood?: JsonFloat;
  /**
   * Number of iterations the tracelog records.
   */
  iterations: number;
};

/**
 * Coalescent prior of a `timetree` run.
 */
export type CoalescentPrior = ({
  kind: 'none';
} & CoalescentPriorNone) | ({
  kind: 'fixed';
} & CoalescentPriorFixed) | ({
  kind: 'optimized';
} & CoalescentPriorOptimized) | ({
  kind: 'skyline';
} & CoalescentPriorSkyline);

/**
 * Unit of a fixed coalescent time scale.
 */
export type FixedTcUnit = 'substitutions-per-site' | 'time';

/**
 * Parameters of a relaxed clock.
 */
export type RelaxedClock = {
  /**
   * Slack: how far the rate of a branch may vary.
   */
  slack: number;
  /**
   * Coupling: how strongly the rates of parent and child branches are tied.
   */
  coupling: number;
};

/**
 * Convergence values of one iteration.
 */
export type IterationRow = {
  /**
   * Iteration number, from 0.
   */
  iteration: number;
  /**
   * Largest change of a node time, in years.
   */
  max_time_change?: JsonFloat;
  /**
   * Root-mean-square change of the node times, in years.
   */
  rms_time_change?: JsonFloat;
  /**
   * Log likelihood of the sequences.
   */
  log_lh_seq?: JsonFloat;
  /**
   * Log marginal likelihood of the node times: branch-time likelihoods relative to each branch's sequence optimum, coalescent prior included.
   */
  log_lh_time?: JsonFloat;
  /**
   * Log likelihood of the coalescent prior.
   */
  log_lh_coal?: JsonFloat;
};

/**
 * One segment of the coalescent time scale.
 */
export type SkylineSegment = {
  /**
   * Start of the segment, as a decimal year.
   */
  start: number;
  /**
   * End of the segment, as a decimal year.
   */
  end: number;
  /**
   * Coalescent time scale in years.
   */
  tc: Band;
  /**
   * Effective population size.
   */
  ne: Band;
};

/**
 * An estimate with an optional confidence band.
 */
export type Band = {
  /**
   * Point estimate.
   */
  value: number;
  /**
   * Lower bound of the band.
   */
  lower?: number;
  /**
   * Upper bound of the band.
   */
  upper?: number;
};

/**
 * Results of an `ancestral` run.
 */
export type AncestralResults = {
  /**
   * Number of nucleotide mutations on all branches.
   */
  mutations: number;
  /**
   * Branches with at least one mutation, most mutations first.
   */
  branches: Array<BranchMutations>;
  /**
   * Sequence positions with substitutions between determined states on more than one branch, most
   * branches first.
   */
  recurrent_sites: Array<RecurrentSite>;
};

/**
 * Mutations on the branch above one node.
 */
export type BranchMutations = {
  /**
   * Name of the node below the branch.
   */
  name: string;
  /**
   * Number of samples below the branch.
   */
  tips: number;
  /**
   * Mutations on the branch.
   */
  mutations: Array<string>;
};

/**
 * A sequence position that mutates on several branches.
 */
export type RecurrentSite = {
  /**
   * Position in the sequence, from 1.
   */
  position: number;
  /**
   * Number of branches with a mutation at the position.
   */
  branches: number;
};

/**
 * The tree before and after an `optimize` or `prune` run.
 */
export type TreeChange = {
  /**
   * Statistics of the input tree; absent when it cannot be read, and the problems of the results name the cause.
   */
  before?: TreeStatistics;
  /**
   * Statistics of the tree the run wrote; absent when the run wrote no Auspice tree.
   */
  after?: TreeStatistics;
  /**
   * Number of nucleotide mutations on all branches of the tree the run wrote.
   */
  mutations: number;
};

/**
 * Size and shape of a tree.
 */
export type TreeStatistics = {
  /**
   * Number of samples.
   */
  samples: number;
  /**
   * Number of internal nodes, the root included.
   */
  internal_nodes: number;
  /**
   * Number of internal nodes with more than two children.
   */
  polytomies: number;
  /**
   * Sum of the branch lengths, in substitutions per site; absent when the tree has no branch lengths.
   */
  total_branch_length?: number;
};

/**
 * A file of a run that could not be read.
 */
export type OutputProblem = {
  /**
   * Path of the file: relative to the run's `out/` folder for an output file, as the run resolved it for an input.
   */
  path: string;
  /**
   * Why the file could not be read.
   */
  message: string;
};

/**
 * Comparison of two runs: their settings and their results.
 */
export type RunComparison = {
  /**
   * Whether both runs are the same analysis, that is, they execute the same command. Runs of different analyses have
   * no settings comparison and no estimates.
   */
  same_analysis: boolean;
  /**
   * Settings and inputs that differ; absent when the runs are different analyses.
   */
  settings?: SettingsComparison;
  /**
   * Changes of the root date and the clock rate, for a one-line summary; present when both runs are finished
   * time-tree runs or finished clock runs, and at least one of the two estimates is known in both.
   */
  delta?: EstimateDelta;
  /**
   * Estimates side by side; present when both runs are finished time-tree runs with a tree.
   */
  estimates?: EstimateComparison;
  /**
   * Date shifts of the ancestors both trees share; present when both runs are finished time-tree runs with a tree.
   */
  ancestors?: AncestorComparison;
};

/**
 * Settings and inputs that differ between two runs of the same command. The settings that the app sets for every
 * run, the output files and their paths, are not compared.
 */
export type SettingsComparison = {
  /**
   * Settings whose resolved values differ, and inputs whose file contents differ.
   */
  differences: Array<SettingDifference>;
  /**
   * Number of settings and inputs compared.
   */
  compared: number;
  /**
   * Whether both runs have the same configuration hash: the same settings on the same input contents.
   */
  same_config_hash: boolean;
};

/**
 * Changes of the main estimates from the first run to the second.
 */
export type EstimateDelta = {
  /**
   * Root date of the second run minus the root date of the first, in days: the dated root of a time tree, or the
   * x-intercept of the root-to-tip regression of a clock run.
   */
  root_date_days?: number;
  /**
   * Change of the clock rate, in percent of the first rate.
   */
  clock_rate_percent?: number;
  /**
   * The changes in one line, for example `Root date -46 d, clock rate -7.9 %`.
   */
  summary: string;
};

/**
 * Estimates of two time-tree runs and their differences, second minus first.
 */
export type EstimateComparison = {
  /**
   * Estimates of the first run.
   */
  first: TimetreeEstimates;
  /**
   * Estimates of the second run.
   */
  second: TimetreeEstimates;
  /**
   * Shift of the root date, in days.
   */
  root_shift_days?: number;
  /**
   * Change of the width of the root-date interval, in days.
   */
  root_interval_change_days?: number;
  /**
   * Change of the clock rate, in percent of the first rate.
   */
  clock_rate_change_percent?: number;
  /**
   * Change of the number of samples the clock model left out.
   */
  excluded_samples_change: number;
  /**
   * Change of the total log likelihood; absent when either value is missing or not finite, or when
   * `log_likelihood_mismatches` is not empty.
   */
  log_likelihood_change?: number;
  /**
   * Why the log likelihoods of the two runs cannot be compared; empty when they can.
   */
  log_likelihood_mismatches: Array<LikelihoodMismatch>;
};

/**
 * A difference between two time-tree runs that changes what their log likelihoods measure, so that their difference
 * is no measure of fit.
 */
export type LikelihoodMismatch = 'data' | 'substitution-model' | 'coalescent-prior' | 'topology';

/**
 * Date shifts of the ancestors two trees share, matched by their set of samples.
 */
export type AncestorComparison = {
  /**
   * Ancestors dated in both trees, with the shift of their date.
   */
  shifts: Array<AncestorShift>;
  /**
   * Number of ancestors in the first tree.
   */
  ancestors: number;
  /**
   * Mean absolute shift, in days.
   */
  mean_absolute_shift_days?: number;
};

/**
 * Date shift of one ancestor between two trees.
 */
export type AncestorShift = {
  /**
   * Name of the ancestor in the first tree.
   */
  name: string;
  /**
   * Number of samples below the ancestor.
   */
  tips: number;
  /**
   * Date in the first tree.
   */
  date_first: YearDate;
  /**
   * Date in the second tree minus the date in the first, in days.
   */
  shift_days: number;
};

/**
 * Request to find a clade of one run in the other time-tree runs.
 */
export type CladeRequest = {
  /**
   * Run whose tree holds the clade.
   */
  run: JobId;
  /**
   * Name of the node at the top of the clade.
   */
  node: string;
};

/**
 * A clade of one run found in the other finished time-tree runs.
 */
export type CladeInRuns = {
  /**
   * Runs whose tree has a node with the same set of samples below it.
   */
  matches: Array<CladeMatch>;
  /**
   * Number of other finished time-tree runs searched.
   */
  searched_runs: number;
  /**
   * Runs whose tree could not be read, with the reason.
   */
  unreadable_runs: Array<UnreadableRun>;
};

/**
 * The node of another run with the same set of samples below it.
 */
export type CladeMatch = {
  /**
   * Id of the run.
   */
  run: JobId;
  /**
   * Title of the run.
   */
  title: string;
  /**
   * Name of the node in that run.
   */
  node: string;
  /**
   * Date of the node.
   */
  date?: YearDate;
  /**
   * Confidence interval of the date.
   */
  date_interval?: DateInterval;
};

/**
 * A run whose tree could not be read.
 */
export type UnreadableRun = {
  /**
   * Id of the run.
   */
  run: JobId;
  /**
   * Why the tree could not be read.
   */
  message: string;
};

/**
 * Event of a run, as stored in the run's `events.jsonl` and sent to subscribers.
 */
export type RunEvent = ({
  type: 'started';
} & RunEventStarted) | ({
  type: 'progress';
} & RunEventProgress) | ({
  type: 'log';
} & RunEventLog) | ({
  type: 'iteration';
} & RunEventIteration) | ({
  type: 'terminal';
} & RunEventTerminal);

/**
 * Identity of an accepted job.
 */
export type JobStarted = {
  job_id: JobId;
  command: AppCommand;
};

export type ProgressEvent = {
  stage: string;
  fraction: number;
  message: string;
};

export type LogEvent = {
  level: LogLevel;
  message: string;
};

export type LogLevel = 'trace' | 'debug' | 'info' | 'warn' | 'error';

/**
 * Convergence values of one timetree optimization iteration, as the tracelog records them, with the clock model the
 * iteration used.
 */
export type IterationEvent = {
  /**
   * Iteration number, starting at 1.
   */
  iteration: number;
  /**
   * Number of ancestral sequence states that changed in this iteration.
   */
  n_diff: number;
  /**
   * Number of nodes added by polytomy resolution in this iteration.
   */
  n_resolved: number;
  /**
   * Largest change of a node time, in years.
   */
  max_time_change?: JsonFloat;
  /**
   * Root-mean-square change of the node times, in years.
   */
  rms_time_change?: JsonFloat;
  /**
   * Log likelihood of the sequences.
   */
  log_lh_seq?: JsonFloat;
  /**
   * Log marginal likelihood of the node times: branch-time likelihoods relative to each branch's sequence optimum, coalescent prior included.
   */
  log_lh_time?: JsonFloat;
  /**
   * Log likelihood of the coalescent prior.
   */
  log_lh_coal?: JsonFloat;
  /**
   * Clock rate of the clock model the iteration used, in substitutions per site per year.
   */
  clock_rate: JsonFloat;
  /**
   * Squared correlation coefficient of the root-to-tip regression of that clock model; absent for a fixed rate.
   */
  r_squared?: JsonFloat;
};

/**
 * How a job ended.
 */
export type TerminalEvent = ({
  status: 'ok';
} & TerminalEventOk) | ({
  status: 'error';
} & TerminalEventError) | ({
  status: 'cancelled';
} & TerminalEventCancelled) | ({
  status: 'interrupted';
} & TerminalEventInterrupted);

/**
 * Result of a command that ran to completion.
 */
export type CommandOutcome = {
  /**
   * Command that ran.
   */
  command: AppCommand;
  /**
   * Files of the command's output plan that exist after the run, sorted by path.
   */
  output_files: Array<OutputFile>;
};

/**
 * Change of the app's runs, sent on the app-wide event stream.
 */
export type AppEvent = ({
  kind: 'run-created';
} & AppEventRunCreated) | ({
  kind: 'run-updated';
} & AppEventRunUpdated) | ({
  kind: 'run-removed';
} & AppEventRunRemoved) | ({
  kind: 'examples-download';
} & AppEventExamplesDownload) | ({
  kind: 'resync';
} & AppEventResync);

/**
 * REST path whose answers a change made stale.
 */
export type StalePath = {
  /**
   * Path of the API, without query string.
   */
  path: string;
  /**
   * Which answers of `path` are stale.
   */
  scope: StaleScope;
};

/**
 * Which answers a stale path covers.
 */
export type StaleScope = 'exact' | 'subtree';

/**
 * Stage of the download of the example datasets.
 */
export type ExamplesDownload = ({
  state: 'idle';
} & ExamplesDownloadIdle) | ({
  state: 'running';
} & ExamplesDownloadRunning) | ({
  state: 'done';
} & ExamplesDownloadDone) | ({
  state: 'failed';
} & ExamplesDownloadFailed);

/**
 * A file uploaded for a run that has not started.
 */
export type UploadedInput = {
  /**
   * File name of the upload.
   */
  name: string;
  /**
   * Path to use for the file in the configurations of runs, checks, and other requests.
   */
  path: string;
  /**
   * Size in bytes.
   */
  size: number;
  /**
   * SHA-256 of the contents, as lowercase hexadecimal.
   */
  sha256: string;
};

/**
 * Settings of a local TreeTime installation, kept in `settings.yaml` or `settings.json` in the app folder. Every
 * setting is optional.
 */
export type AppSettings = {
  /**
   * Folders of the app. Each defaults to a folder of the same name in the app folder.
   */
  paths?: AppPathSettings;
  /**
   * Preferences of the user interface.
   */
  ui?: UiSettings;
  /**
   * Settings of the analyses that the app runs.
   */
  analysis?: AnalysisSettings;
};

/**
 * Folders of the app. A relative path is relative to the app folder. The environment variables
 * `TREETIME_PROFILE_DIR`, `TREETIME_RUNS_DIR`, `TREETIME_LOGS_DIR`, and `TREETIME_EXAMPLES_DIR` take precedence.
 */
export type AppPathSettings = {
  /**
   * Browser profile of the desktop app: cache, local storage, and crash reports. Default: `profile`.
   */
  profile?: string;
  /**
   * Runs, each in its own folder. Default: `runs`.
   */
  runs?: string;
  /**
   * Logs and crash diagnostics. Default: `logs`.
   */
  logs?: string;
  /**
   * Example datasets and configurations that the app lists. Default: `examples`.
   */
  examples?: string;
};

/**
 * Preferences of the user interface. Unset preferences take the defaults of the user interface.
 */
export type UiSettings = {
  /**
   * Color theme.
   */
  theme?: UiTheme;
  /**
   * Width of the sidebar in pixels.
   */
  sidebar_width?: number;
  /**
   * The unfinished analysis form.
   */
  draft?: UiDraft;
};

/**
 * Color theme of the user interface.
 */
export type UiTheme = 'light' | 'dark' | 'system';

/**
 * The unfinished analysis form: the command, its settings, and how the form is shown.
 */
export type UiDraft = {
  command: AppCommand;
  /**
   * Settings of the command, as in a configuration file.
   */
  config: SparseConfig;
  /**
   * Where each input file came from, by setting key.
   */
  sources: {
    [key: string]: UiDraftSource;
  };
  /**
   * The run whose settings the form was loaded from.
   */
  from_run_id?: JobId;
  /**
   * The run that holds the uploaded input files of the form.
   */
  upload_run_id?: JobId;
  /**
   * The options that the form picked for the choices of the command, which `configCheck` takes as `choices`.
   */
  choices: Array<ActiveChoice>;
  view: UiSettingsView;
  /**
   * Text of the settings search field.
   */
  search: string;
  /**
   * Whether the form shows only the settings that differ from their defaults.
   */
  changed_only: boolean;
  code_format: UiCodeFormat;
};

/**
 * Origin of an input file of the form.
 */
export type UiDraftSource = {
  /**
   * Name of the file shown in the form.
   */
  label: string;
  origin: UiDraftOrigin;
  /**
   * Size of the file in bytes, when known.
   */
  size?: number;
  /**
   * The run the file came from: the run that received the upload, or the earlier run whose input the file is. The
   * form drops the file when this run no longer exists, because the file may be stored in the folder of that run.
   */
  run_id?: JobId;
};

/**
 * Where an input file of the form came from.
 */
export type UiDraftOrigin = ({
  kind: 'dataset';
} & UiDraftOriginDataset) | ({
  kind: 'example';
} & UiDraftOriginExample) | ({
  kind: 'upload';
} & UiDraftOriginUpload) | ({
  kind: 'local';
} & UiDraftOriginLocal) | ({
  kind: 'run';
} & UiDraftOriginRun) | ({
  kind: 'config';
} & UiDraftOriginConfig);

/**
 * Which settings the form shows.
 */
export type UiSettingsView = 'main' | 'all';

/**
 * Format of the code that reproduces the form.
 */
export type UiCodeFormat = 'cli' | 'yaml';

/**
 * Settings of the analyses that the app runs. A setting here applies to every run whose configuration does not set
 * it.
 */
export type AnalysisSettings = {
  /**
   * Largest number of points of one probability grid during time inference, for runs whose configuration does not
   * set `max_grid_points`. Unset: 1000000.
   */
  max_grid_points?: number;
};

/**
 * The examples folder of a local app, with the index of the example data it holds.
 */
export type ExamplesFolder = {
  /**
   * Absolute path of the examples folder; the paths of the index are relative to it.
   */
  folder: string;
  /**
   * Index of the example data in the folder, read from its `index.json`. Unset when the folder holds no index, for
   * example before the example datasets are downloaded.
   */
  index?: DataIndex;
};

/**
 * Index of the example data in the `data/` folder of the repository: every tracked file outside hidden files and
 * folders, the datasets, the example configurations of the commands, and the example pipelines. Every path is relative to `data/` and uses `/`
 * separators. The apps read the example data only through this index.
 */
export type DataIndex = {
  /**
   * Every tracked file of the data folder except the index itself and hidden files and folders (a path component
   * that starts with `.`), sorted by path.
   */
  files: Array<IndexedFile>;
  /**
   * Folders that hold a `tree.nwk`, with the files that fill command inputs, sorted by name.
   */
  datasets: Array<IndexedDataset>;
  /**
   * Example configurations of the commands the application runs, sorted by path.
   */
  configs: Array<IndexedConfig>;
  /**
   * Example pipeline configurations, sorted by path.
   */
  pipelines: Array<IndexedPipeline>;
};

/**
 * A tracked file of the data folder.
 */
export type IndexedFile = {
  /**
   * Path relative to the data folder.
   */
  path: string;
  /**
   * Size in bytes.
   */
  size: number;
};

/**
 * A folder of the data folder that holds a `tree.nwk`.
 */
export type IndexedDataset = {
  /**
   * Path of the folder relative to the data folder.
   */
  name: string;
  /**
   * The files of the folder that fill command inputs, at most one per kind. A compressed file fills the input of its
   * uncompressed name.
   */
  inputs: Array<IndexedInput>;
  /**
   * Organism of the samples, from the `organism` field of the front matter of the folder's `README.md`, for example
   * `Zika virus`.
   */
  organism: string;
  /**
   * Genome segment of the sequences, for a segmented genome, from the `segment` field of the same front matter, for
   * example `NA`.
   */
  segment?: string;
  /**
   * Number of samples: the tips of the tree.
   */
  samples: number;
  /**
   * Earliest and latest sampling date of the metadata, when the dataset has dates.
   */
  dates?: DateSpan;
  /**
   * Number of sites of the alignment, when the dataset has an alignment.
   */
  sequence_length?: number;
  /**
   * Settings that the commands need to read the files of the dataset, in configuration form, from the `settings`
   * field of the front matter of the folder's `README.md`, for example `metadata_id_columns: [genbank_accession]`
   * when the tip names of the tree are in a metadata column that is not one of the default name columns. The facts
   * of the dataset are read with these settings. Left out when the dataset needs none.
   */
  settings?: SparseConfig;
};

/**
 * A file of a dataset that fills a command input.
 */
export type IndexedInput = {
  /**
   * Input the file fills.
   */
  kind: InputKind;
  /**
   * Path of the file relative to the data folder.
   */
  path: string;
};

/**
 * An example configuration of one command.
 */
export type IndexedConfig = {
  /**
   * Path of the file relative to the data folder.
   */
  path: string;
  /**
   * Command the configuration is for, taken from the `$schema` URL of its `yaml-language-server` directive. It may be
   * a command that only the command-line tool runs.
   */
  command: string;
  /**
   * Title of the example: the first comment line after the directive.
   */
  title: string;
  /**
   * Folder of the file relative to the data folder, which relative paths in the file resolve from.
   */
  folder: string;
  /**
   * Text of the file.
   */
  content: string;
  /**
   * The files that each input setting of the configuration reads, relative to the data folder, by setting key.
   */
  inputs: {
    [key: string]: Array<string>;
  };
};

/**
 * An example pipeline configuration.
 */
export type IndexedPipeline = {
  /**
   * Path of the file relative to the data folder.
   */
  path: string;
  /**
   * Title of the example: the first comment line after the directive.
   */
  title: string;
  /**
   * Steps of the pipeline, in the order they run.
   */
  steps: Array<IndexedStep>;
};

/**
 * One step of an example pipeline.
 */
export type IndexedStep = {
  /**
   * Name of the step.
   */
  name: string;
  /**
   * Command the step runs. It may be a command that only the command-line tool runs.
   */
  command: string;
};

/**
 * The download of the example datasets, with the app event that reported it last.
 */
export type ExamplesDownloadStatus = {
  download: ExamplesDownload;
  /**
   * Sequence number of the last app event about the download. A client keeps whichever of this answer and the
   * events it received has the higher number.
   */
  seq?: number;
};

/**
 * The runs folder of the running back end, and the folder used when the settings name none.
 */
export type Workspace = {
  /**
   * The runs folder in use.
   */
  path: string;
  /**
   * The runs folder used when the settings name none: `runs` in the app folder.
   */
  default_path: string;
  /**
   * The environment variable that sets the runs folder; the app cannot change the folder then.
   */
  fixed_by?: string;
  /**
   * Why the runs folder named in the settings could not be opened. The default runs folder is in use then.
   */
  error?: string;
};

/**
 * A new runs folder. It takes effect when the back end starts again.
 */
export type WorkspaceUpdate = {
  /**
   * Absolute path of the folder. Unset: `runs` in the app folder.
   */
  path?: string;
};

/**
 * Where to save an output file of a run, or its run package.
 */
export type SaveRunRequest = {
  /**
   * Path of the file relative to the run's `out/` folder. Unset: the run package, a zip archive that recreates the
   * run in the app and reproduces it with the command-line tool.
   */
  path?: string;
  /**
   * Absolute path of the file to write.
   */
  destination: string;
};

/**
 * Settings of one command.
 */
export type CommandSettings = {
  /**
   * The command.
   */
  command: AppCommand;
  /**
   * Name of the analysis as the app shows it, for example `Time tree`.
   */
  title: string;
  /**
   * One sentence on what the analysis does.
   */
  description: string;
  /**
   * Input files the command reads, in the order the form asks for them.
   */
  inputs: Array<InputSlot>;
  /**
   * Whether the command reads sampling dates from the metadata.
   */
  uses_dates: boolean;
  /**
   * Setting groups, in the order `treetime <command> --help` lists their headings.
   */
  groups: Array<string>;
  /**
   * Sections of the settings form in display order, one per purpose: the settings of the purpose that the app does not
   * set, by group.
   */
  sections: Array<SettingSection>;
  /**
   * The settings the form shows first, in rows of settings that it edits together, in the order it shows them.
   */
  main_rows: Array<MainSettingRow>;
  /**
   * Settings that the form shows as one choice between options.
   */
  choices: Array<SettingChoice>;
  /**
   * Every setting of the command, by group, in the order `--help` lists them.
   */
  settings: Array<SettingSpec>;
};

/**
 * An input file of a command, as the form asks for it.
 */
export type InputSlot = {
  /**
   * Kind of the file; also the setting that names it.
   */
  kind: InputKind;
  /**
   * Whether a run of the app needs the file.
   */
  need: InputNeed;
  /**
   * Name of the input, for example `Tree`.
   */
  label: string;
  /**
   * File formats the readers accept, for example `Newick`.
   */
  formats: string;
  /**
   * File name extensions of the accepted formats, compressed forms included, without the dot.
   */
  extensions: Array<string>;
  /**
   * Whether the setting takes a list of files.
   */
  list: boolean;
};

/**
 * How much a run of the app needs an input file.
 */
export type InputNeed = 'required' | 'recommended' | 'optional';

/**
 * One section of the settings form: the settings of one purpose.
 */
export type SettingSection = {
  /**
   * Purpose of the settings of the section.
   */
  purpose: SettingPurpose;
  /**
   * Heading of the section, for example `Output format`.
   */
  title: string;
  /**
   * Groups of the section, in the order of `groups`; each has a setting of the purpose that the app does not set.
   */
  groups: Array<string>;
};

/**
 * One row of the main settings: one or more settings that the form shows and edits together.
 */
export type MainSettingRow = {
  /**
   * Name of the row, for example `Coalescent prior`.
   */
  label: string;
  /**
   * Short line under the name, for example `Tree prior on node times`.
   */
  description?: string;
  /**
   * The settings of the row, in the order the row shows them.
   */
  settings: Array<RowSetting>;
  /**
   * The control that edits the settings.
   */
  control: RowControl;
};

/**
 * One setting of a row of the main settings.
 */
export type RowSetting = {
  /**
   * Key of the setting.
   */
  key: string;
  /**
   * Name of the setting inside the row, for example `Rate` in the row `Clock rate`.
   */
  label: string;
};

/**
 * Control of a row of the main settings.
 */
export type RowControl = ({
  kind: 'choice';
} & RowControlChoice) | ({
  kind: 'switches';
} & RowControlSwitches) | ({
  kind: 'coalescent';
} & RowControlCoalescent) | ({
  kind: 'clock-filter';
} & RowControlClockFilter) | ({
  kind: 'substitution-model';
} & RowControlSubstitutionModel) | ({
  kind: 'setting';
} & RowControlSetting);

/**
 * A switch of a row of the main settings.
 */
export type RowSwitch = {
  /**
   * Key of the setting the switch turns on or off.
   */
  key: string;
  /**
   * Text beside the switch.
   */
  text: string;
  /**
   * Whether the switch is on while the setting is off: the setting turns off a step that runs by default.
   */
  inverted: boolean;
};

/**
 * An option of a row of the main settings.
 */
export type RowOption = {
  /**
   * The option, for example `skyline`.
   */
  value: string;
  /**
   * Name of the option, for example `Skyline`.
   */
  label: string;
  /**
   * What the option does, as the form shows it while the option is picked.
   */
  note?: string;
};

/**
 * Settings that the form shows as one choice between options, for example the clock rate.
 */
export type SettingChoice = {
  choice: ChoiceName;
  /**
   * Keys of the settings the choice controls.
   */
  keys: Array<string>;
  /**
   * The options, in the order the form shows them.
   */
  options: Array<ChoiceOption>;
};

/**
 * One option of a choice.
 */
export type ChoiceOption = {
  option: ChoiceOptionName;
  /**
   * Name of the option, for example `Fixed rate`.
   */
  label: string;
  /**
   * What the option does, as the form shows it while the option is picked.
   */
  note?: string;
  /**
   * Changes that picking the option makes: settings it writes, and settings it removes so that they take their
   * defaults.
   */
  patch: Array<SettingPatch>;
  /**
   * Keys of the settings the form shows while the option is picked.
   */
  settings: Array<string>;
};

/**
 * One setting of a command.
 */
export type SettingSpec = {
  /**
   * Key of the setting in the configuration, for example `clock_rate`.
   */
  key: string;
  /**
   * Name of the setting as the form shows it, for example `Clock rate std. dev.`.
   */
  label: string;
  /**
   * Command-line flag, for example `--clock-rate`.
   */
  flag: string;
  /**
   * Heading of the setting in `--help`.
   */
  group: string;
  /**
   * What the setting is for, which places it in the form.
   */
  purpose: SettingPurpose;
  /**
   * Whether the app sets the setting for every run, as it does for the output files and their selection, so that
   * the form does not offer it and comparisons of configurations skip it.
   */
  set_by_app: boolean;
  /**
   * What the setting names: a file, or a value.
   */
  role: SettingRole;
  /**
   * Form of the value, which selects the control that edits it.
   */
  kind: SettingKind;
  /**
   * Whether the setting can be unset.
   */
  nullable: boolean;
  /**
   * Allowed values of an `enum`, `enum-or-text` or `enum-list` setting.
   */
  options: Array<SettingOption>;
  /**
   * Type of the items of a `list` setting.
   */
  item_kind: ListItemKind;
  /**
   * Fields of the entries of a `records` setting, in the order of the configuration.
   */
  fields: Array<RecordFieldSpec>;
  /**
   * Value of the setting when the configuration does not set it; absent when the setting has no default.
   */
  default_value?: JsonValue;
  /**
   * Value the run uses when the configuration does not set the setting, for a setting without `default_value` that
   * applies only together with another setting: the run checks it only when a configuration sets it.
   */
  documented_default?: JsonValue;
  /**
   * Smallest allowed value of a number, when there is one.
   */
  minimum?: number;
  /**
   * Typical values of the setting, as the configuration spells them; the first one is the value the form fills in
   * when the setting is turned on.
   */
  examples: Array<JsonValue>;
  /**
   * Names of the values the command-line flag takes, in order, for example `SLACK` and `COUPLING`.
   */
  value_names: Array<string>;
  /**
   * Keys of the settings this setting cannot be used together with, as the command line rejects them.
   */
  conflicts: Array<string>;
  /**
   * First paragraph of the setting's description.
   */
  help: string;
  /**
   * Remaining paragraphs of the setting's description.
   */
  more: string;
};

/**
 * What a setting names.
 */
export type SettingRole = 'setting' | 'input' | 'input-template' | 'output';

/**
 * Form of a setting's value.
 */
export type SettingKind = 'switch' | 'enum' | 'enum-or-text' | 'integer' | 'number' | 'text' | 'list' | 'enum-list' | 'records';

/**
 * One allowed value of a setting.
 */
export type SettingOption = {
  /**
   * The value, as the configuration spells it.
   */
  value: string;
  /**
   * Name of the value as the form shows it, for example `Least squares`.
   */
  label: string;
  /**
   * Description of the value, when it has one.
   */
  help: string;
};

/**
 * Type of the items of a list setting.
 */
export type ListItemKind = 'string' | 'number' | 'integer';

/**
 * One field of the entries of a `records` setting.
 */
export type RecordFieldSpec = {
  /**
   * Key of the field in an entry, for example `name`.
   */
  key: string;
  /**
   * Name of the field as the form shows it, for example `Name`.
   */
  label: string;
  /**
   * Form of the value, which selects the control that edits it; never `records`.
   */
  kind: SettingKind;
  /**
   * Whether an entry can leave the field out.
   */
  nullable: boolean;
  /**
   * Allowed values of an `enum`, `enum-or-text` or `enum-list` field.
   */
  options: Array<SettingOption>;
  /**
   * Type of the items of a `list` field.
   */
  item_kind: ListItemKind;
  /**
   * Value the command uses when an entry leaves the field out, as the form shows it; absent when the field has none.
   */
  documented_default?: JsonValue;
  /**
   * Typical values of the field, as the configuration spells them.
   */
  examples: Array<JsonValue>;
  /**
   * First paragraph of the field's description.
   */
  help: string;
  /**
   * Remaining paragraphs of the field's description.
   */
  more: string;
};

/**
 * Settings of every command the app runs, as the settings form shows them.
 */
export type SettingCatalog = {
  /**
   * Settings of each command.
   */
  commands: Array<CommandSettings>;
};

/**
 * One partition: a set of sites of one `--alignment` file and its substitution model
 */
export type PartitionSpec = {
  /**
   * Name of the partition in outputs and messages
   */
  name?: string;
  /**
   * Number of the alignment file in the `--alignment` list (1, 2, ...); may be left out when the list has one file
   */
  alignment?: number;
  /**
   * Sites of the partition, as site ranges numbered from 1: `a`, `a-b`, or `a-b\k` for every k-th site from a to b
   *
   * Left out, the partition takes every site of its alignment that no other entry takes.
   */
  sites?: Array<string>;
  /**
   * Substitution model of the partition
   */
  model?: GtrModelName;
  /**
   * Parameters of the model of the partition, as the `key=value` items of `--model-params`, for example `kappa=4`
   */
  model_params?: Array<string>;
};

export type GtrModelName = 'jc69' | 'k80' | 'f81' | 'hky85' | 't92' | 'tn93' | 'jtt92' | 'infer';

export type RerootMethod = 'least-squares' | 'min-dev' | 'oldest' | 'midpoint';

export type BranchLengthMode = 'auto' | 'input' | 'marginal';

export type PartitionRates = 'estimate' | 'equal';

export type Representation = 'auto' | 'dense' | 'sparse';

export type GapFill = 'only-terminal' | 'all' | 'none';

export type NewickAnnotationsArg = 'plain' | 'beast' | 'nhx';

export type TimetreeOutputSelection = 'all' | 'nwk' | 'nexus' | 'auspice' | 'mat-pb' | 'mat-json' | 'graph-json' | 'dot' | 'node-data' | 'model' | 'sequences' | 'clock-model' | 'rtt' | 'dates' | 'tracelog' | 'coalescent' | 'coalescent-json';

export type DivergenceUnits = 'mutations-per-site' | 'mutations';

/**
 * Reconstructed nucleotide FASTA
 */
export type TimetreeAmbiguityOutput = 'sequences';

export type TopologyOrderArg = 'keep' | 'descendant-count' | 'descendant-count-reverse' | 'height' | 'height-reverse' | 'divergence' | 'divergence-reverse' | 'label' | 'label-reverse' | 'target-order' | 'target-order-reverse';

export type TopologyOrderTargetAggregateArg = 'mean' | 'median';

/**
 * Infer a time-scaled tree from a tree, the sampling dates of its tips, and optionally an alignment
 */
export type TimetreeConfig = {
  /**
   * Aligned FASTA input
   *
   * Each `--alignment` file is numbered by its position in the list (1, 2, ...) and is one partition, unless
   * `--partition` entries of `ancestral`, `optimize`, or `timetree` split it into several. A path that ends in `.gz`,
   * `.bz2`, `.xz`, or `.zst` reads a compressed file. Use `-` to read uncompressed input from standard input (stdin);
   * `-` may appear at most once.
   */
  alignment?: Array<string>;
  /**
   * One partition: a set of sites of one `--alignment` file with its own substitution model; repeat the flag for each
   * partition
   *
   * Without `--partition`, each `--alignment` file is one partition with the model of `--model`. An entry is a YAML
   * or JSON map with the keys `name` (the name of the partition in outputs and messages), `alignment` (the number of
   * its `--alignment` file, 1, 2, ...; required with two or more files), `sites` (a list of site ranges, numbered
   * from 1: `a`, `a-b`, or `a-b\k` for every k-th site from a to b), `model` (the substitution model, default `infer`)
   * and `model_params` (the `key=value` items of `--model-params` for that model). Each entry carries its own model,
   * so `--model` and `--model-params` cannot be used together with `--partition`. Every alignment needs at least one
   * entry, and every site belongs to exactly one entry. An entry without `sites` takes the sites that the other entries
   * of its alignment leave; one entry per alignment can leave out `sites`. Write site ranges in single quotes or
   * without quotes, because YAML reads a backslash in double quotes as an escape. Example: `--partition "{name: cp1,
   * sites: ['101-1600\3']}" --partition "{name: cp2, sites: ['102-1600\3']}" --partition "{name: cp3, sites:
   * ['103-1600\3'], model: hky85, model_params: ['kappa=4']}" --partition "{name: noncoding}"`.
   */
  partition?: Array<PartitionSpec>;
  /**
   * Tree in Newick format
   *
   * A path that ends in `.gz`, `.bz2`, `.xz`, or `.zst` reads a compressed file.
   */
  tree?: string;
  /**
   * Newick dialect of the tree inputs (the tree and the reference topology)
   *
   * A dialect is a tree structure and an annotation convention, written as `<structure>,<annotations>`. The
   * structure is classic (plain labels and branch lengths), enewick (hybrid nodes such as `x#H1`) or rich (eNewick
   * with support and probability fields). The annotations are plain (comments are text), beast (`[&key=value]`), nhx
   * (`[&&NHX:key=value]`) or mrbayes (`[&B name value]`). For example, `enewick,beast` reads networks with BEAST
   * annotations and `classic,nhx` reads NHX trees. TreeTime reads trees only, so a network input is an error.
   */
  newick_dialect?: 'classic,plain' | 'classic,beast' | 'classic,nhx' | 'classic,mrbayes' | 'enewick,plain' | 'enewick,beast' | 'enewick,nhx' | 'enewick,mrbayes' | 'rich,plain' | 'rich,beast' | 'rich,nhx' | 'rich,mrbayes';
  /**
   * Treat tree tips that have no sequence in the alignment as fully ambiguous (missing data) instead of aborting.
   *
   * Without this flag the run aborts when more than one third of the tips lack a sequence, because the alignment may
   * not belong to the tree. Useful for per-CDS translations, where some samples have no peptide for a given CDS.
   */
  allow_missing_sequences?: boolean;
  /**
   * Metadata table (CSV or TSV) with one row per sample
   *
   * `--metadata-id-columns` names the column that links a row to a tree tip. The other columns hold the data of the
   * sample, such as its sampling date or its traits. A path that ends in `.gz`, `.bz2`, `.xz`, or `.zst` reads a
   * compressed file.
   */
  metadata?: string;
  /**
   * Candidate column name(s) holding the taxon identifier that links metadata to tree tips
   *
   * The first listed column that is present in the header is used. Matching is case-insensitive.
   */
  metadata_id_columns?: Array<string>;
  /**
   * Candidate field delimiter(s) for the metadata table
   *
   * The delimiter actually present in the file is used. Defaults to comma, tab, and semicolon.
   */
  metadata_delimiters?: Array<string>;
  /**
   * Label of the column to be used as sampling date (auto-detected when omitted)
   */
  date_column?: string;
  /**
   * Format used to parse string sampling dates (numeric, ISO, and uncertain dates parse regardless)
   */
  date_format?: string;
  /**
   * Length of the sequences, used to calculate the expected variation of the branch lengths
   *
   * Required without `--alignment`, and applies only then: with an alignment, the run takes the length from the
   * alignment.
   */
  sequence_length?: number;
  /**
   * Alphabet of the sequences
   *
   * `nuc` (default): nucleotides A, C, G and T, with the IUPAC ambiguity codes and `N` for an unknown base. `aa`: the
   * 20 amino acids and the stop codon `*` as a 21st state, with `X` for an unknown residue. `aa-no-stop`: the 20
   * amino acids without a state for the stop codon.
   */
  alphabet?: AlphabetName;
  /**
   * Report sequence positions counted from 0 instead of 1.
   *
   * Applies to the mutations in the comments of Newick and Nexus trees and to the positions of the homoplasy
   * report. Auspice JSON, augur node data, and UShER MAT outputs count from 1, as their formats require. An input
   * table with positions, such as `--drms`, is always counted from 1.
   */
  zero_based?: boolean;
  /**
   * Fixed rate of the molecular clock, in substitutions per site per year
   *
   * Without this setting, the run estimates the rate.
   */
  clock_rate?: number;
  /**
   * Standard deviation of the provided clock rate estimate
   *
   * Applies only with `--confidence`, whose date intervals include the clock rate uncertainty.
   */
  clock_std_dev?: number;
  /**
   * Use an autocorrelated relaxed clock with the given prior strengths, for example `--relax 1.0 0.5`
   *
   * SLACK is the strength of the Gaussian prior on the rate deviation of each branch, and COUPLING the strength of
   * the coupling of the rates of parent and child branches. Values around 1.0 give weak priors; larger values
   * constrain the rate deviations more strongly. A COUPLING of 0 (`--relax 1.0 0`) gives an uncorrelated clock.
   */
  relax?: Array<number>;
  /**
   * Ignore tips that do not follow a loose clock: the number of interquartile ranges from the root-to-tip regression
   * beyond which a tip is an outlier.
   *
   * 0 switches the filter off.
   */
  clock_filter?: number;
  /**
   * Allow negative clock rates.
   *
   * By default, rates are forced to be positive. For trees with little temporal signal, removing this restriction
   * gives essentially mid-point rooting.
   */
  allow_negative_rate?: boolean;
  /**
   * Remove the tips that the clock filter flags from the tree.
   *
   * The clock filter flags a tip and leaves it in the tree by default. With this flag, the run removes the flagged tips
   * after the filter: timetree before the time inference, and clock before the final clock fit. Every output leaves the
   * removed tips out, and a run warning names them. The tips that --keep-tips and --keep-tips-file name stay in the
   * tree, flagged. Requires the clock filter (--clock-filter above 0).
   *
   * augur refine with a clock filter (--clock-filter-iqd) removes the flagged tips and also the tips without a usable
   * date. To remove the same tips, add --prune-undated-tips.
   */
  prune_filtered_tips?: boolean;
  /**
   * Remove the tips without a usable date from the tree.
   *
   * A tip has no usable date when the metadata gives no date for it, or a value that is not a date, a numeric date, or
   * a date range. Such a tip stays in the tree by default: timetree infers its date from the tree, and the clock fit
   * leaves it out. With this flag, the run removes these tips: timetree before the time inference, and clock before
   * the final clock fit. Every output leaves the removed tips out, and a run warning names them. The tips that
   * --keep-tips and --keep-tips-file name stay in the tree.
   *
   * Together with --prune-filtered-tips, the run removes the same tips as augur refine with a clock filter
   * (--clock-filter-iqd).
   */
  prune_undated_tips?: boolean;
  /**
   * Names of tips that stay in the tree when --prune-filtered-tips or --prune-undated-tips removes tips
   *
   * Accepts several names, separated by commas or spaces. A kept flagged tip stays flagged: the clock fit leaves it
   * out, and timetree dates it from the tree, as it dates a kept tip without a usable date. Names that match no tip are
   * ignored.
   */
  keep_tips?: Array<string>;
  /**
   * File with names of tips that stay in the tree when --prune-filtered-tips or --prune-undated-tips removes tips, one
   * name per line
   *
   * Surrounding whitespace is trimmed and empty lines are ignored. Names that match no tip are ignored, so the file
   * can list samples of several datasets. A path that ends in `.gz`, `.bz2`, `.xz`, or `.zst` reads a compressed file.
   * Use `-` to read uncompressed input from standard input (stdin).
   */
  keep_tips_file?: string;
  /**
   * Method that chooses the root of the tree
   *
   * `least-squares` and `oldest` use the sampling dates; `min-dev` and `midpoint` use only the branch lengths, root
   * once on the input branch lengths, and count every tip. Without a rooting setting the tree is rerooted by
   * least-squares. Use --outgroup to root on named tips, or --keep-root to keep the input root.
   */
  reroot?: RerootMethod;
  /**
   * Root the tree on the branch above the most recent common ancestor of the named tips
   *
   * With one tip, the root is placed on the branch leading to that tip.
   */
  outgroup?: Array<string>;
  /**
   * Keep the root of the input tree instead of rerooting it.
   */
  keep_root?: boolean;
  /**
   * How the branch lengths of the time inference are obtained
   *
   * `auto` keeps the input branch lengths without an alignment, and also when the longest input branch is longer
   * than 0.1 substitutions per site, because the re-estimated branch lengths are accurate only at short evolutionary
   * distances; otherwise it re-estimates them as `marginal` does. When no input branch has a length, `auto` chooses
   * `marginal`. The run logs the choice.
   */
  branch_length_mode?: BranchLengthMode;
  /**
   * Maximum number of iterations of the inference loop
   *
   * Polytomy resolution and coalescent models of the time inference need at least 2 iterations.
   */
  max_iter?: number;
  /**
   * Estimate the 90% intervals of the node dates
   *
   * Runs a final marginal round of the time inference after the iterations and writes the 90% interval of every
   * dated node. The intervals include the clock rate uncertainty when one is known: `--clock-std-dev` for a given
   * rate, or the Gaussian estimate of an estimated rate. The rate uncertainty is added by inferring the dates again
   * at the rate plus and minus one standard deviation and combining both parts in quadrature.
   */
  confidence?: boolean;
  /**
   * Largest number of points of one probability grid during time inference
   *
   * A run stops with an error when a grid would need more points. The value bounds single grids, not the total
   * memory of a run. When unset, the run takes the limit of the app or server that runs it, otherwise 1000000.
   */
  max_grid_points?: number;
  /**
   * Keep the polytomies of the input tree
   *
   * Without this flag, each polytomy is resolved into binary mergers by the node dates. The resolution is
   * stochastic: the run logs the seed it draws, and `--seed` reproduces the run.
   */
  keep_polytomies?: boolean;
  /**
   * Disable collapsing of short internal branches.
   *
   * By default, before the time inference, internal edges shorter than 0.1/L (L is the number of sites of all
   * alignments) with no substitution in the marginal reconstruction are contracted, as in optimize and TreeTime 0.x.
   * The substitutions of a contracted edge move to its child edges, and the nodes it joined become one polytomy.
   * Edges above internal nodes with a date are kept. When set, such edges are kept.
   */
  no_collapse_short_branches?: boolean;
  /**
   * Coalescent prior: a fixed time scale in substitutions per site (as in TreeTime 0.x and augur, for example 0.01)
   * or as a time (10y, 26w, 90d); opt fits a constant time scale; skyline fits a piecewise-constant one
   *
   * A time is a positive number directly followed by the unit y (years), w (weeks) or d (days). A time scale in
   * substitutions per site is converted to years with the clock rate of each iteration. Without this setting the node
   * times have no coalescent prior.
   */
  coalescent?: number | string | 'opt' | 'skyline';
  /**
   * Number of grid points of the skyline coalescent model
   *
   * Applies only to `--coalescent skyline`. Sets how many piecewise linear segments model Tc(t) over time. Must be at
   * least 2.
   */
  n_skyline?: number;
  /**
   * Smoothing stiffness of the skyline coalescent model
   *
   * Penalizes log-fold-changes of the coalescent time scale Tc between adjacent
   * skyline segments: with z = ln Tc, the objective adds
   * `(stiffness/2) * Σ (ln(Tc_{i+1}/Tc_i))^2`. Because it acts on log Tc, the
   * stiffness is dimensionless and scale-independent. Larger values enforce a
   * smoother Tc(t). Applies only to `--coalescent skyline`.
   */
  skyline_stiffness?: number;
  /**
   * Width of the bands of the coalescent time scale Tc, in standard deviations
   *
   * Applies only to the inferred coalescent priors (`--coalescent opt` and `--coalescent skyline`).
   * The band spans `Tc * exp(±confidence * σ)`, where `σ` is
   * the standard deviation of `ln Tc` from the coalescent likelihood curvature. A fixed
   * time scale is not inferred and therefore has no band.
   */
  coalescent_confidence?: number;
  /**
   * Generations per year, to convert the coalescent time scale Tc into an effective population size
   *
   * The coalescent output reports an effective population size `N_e = Tc * gen_per_year`. Tc is
   * already in calendar years, so this factor rescales it into generation units, the standard
   * axis of a skyline plot. Only affects the reported `N_e`; it does not enter the inference. Applies only with
   * `--coalescent`.
   */
  gen_per_year?: number;
  /**
   * Substitution model to use
   *
   * `infer` infers a model from the data of each partition; each `--alignment` file is one partition. Alternatively,
   * name the model type. If the named model takes parameters, use `--model-params` to set them. The model applies to
   * every file. In commands with `--partition`, each entry carries its own model, so `--model` is an error next to
   * entries.
   */
  model?: GtrModelName;
  /**
   * Parameters for the model selected by `--model`, given as space-separated `key=value` items
   *
   * The parameters apply to the model of every partition; each `--alignment` file is one partition. In commands
   * with `--partition`, each entry carries its own model and parameters, so `--model-params` is an error next to
   * entries. Keys: `mu` (the overall substitution rate, every named model), `kappa` (the transition to transversion
   * ratio of `k80`, `hky85` and `t92`), `kappa1` and `kappa2` (the rate ratios of `tn93`), `pi` (the equilibrium
   * frequencies of `f81`, `hky85` and `tn93`: comma-separated numbers, one frequency per state of the alphabet in its
   * order, for example A, C, G and T for nucleotides, normalized to sum 1; also `pis`, `Pi`, `Pis`) and `pi_GC` (the
   * GC content of `t92`, between 0 and 1). A key left out keeps its default. Example: `--model hky85 --model-params
   * kappa=0.2 pis=0.25,0.25,0.25,0.25`.
   */
  model_params?: Array<string>;
  /**
   * Relative substitution rates of the partitions
   *
   * Each `--alignment` file is one partition, or each `--partition` entry when there are entries. With two or more
   * partitions, all partitions share the branch lengths, and each partition has one relative rate that scales them for
   * the sites of that partition. `estimate` fits the rate of each partition with the rest of its substitution model
   * fixed (a partition with `--model infer` starts from its fitted rate), then divides all rates by their mean
   * weighted by the number of sites of each partition, so that this mean is 1. The branch lengths are then expected
   * substitutions per site, averaged over all sites of all partitions. `equal` fixes the rate of every partition at 1.
   *
   * The setting applies only with two or more partitions.
   */
  partition_rates?: PartitionRates;
  /**
   * Representation of the sequences on the tree
   *
   * The dense representation stores the probabilities of every state at every alignment position of each node; the
   * sparse representation stores only the variable positions. Dense is more accurate when branches are long and many
   * sites change, but uses more memory.
   */
  representation?: Representation;
  /**
   * How to handle the gap characters of the input sequences
   *
   * `only-terminal` (default, as in TreeTime 0.x): replace the leading and trailing gaps of each sequence with the
   * unknown character of the alphabet (`N` or `X`). `all`: replace every gap with the unknown character. `none`: keep
   * every gap.
   */
  gap_fill?: GapFill;
  /**
   * Emit reconstructed leaf (tip) sequences in addition to internal nodes.
   */
  include_leaves?: boolean;
  /**
   * Same as `--include-leaves --impute-missing-data`: emit tip sequences with ambiguous and unknown states resolved to
   * the most likely inferred state.
   */
  reconstruct_tip_states?: boolean;
  /**
   * Include branch mutations from or to the fully ambiguous state (`N` for nucleotides, `X` for amino acids).
   *
   * By default these mutations are omitted from the branch mutations of the Newick and Nexus annotations, the Auspice
   * JSON, and the `muts` and `aa_muts` lists of augur node data. Other ambiguity codes, such as `K` or `R`, are always
   * reported. The flag does not affect the MAT outputs, which store `N` as missing data and never contain these
   * mutations.
   */
  report_ambiguous?: boolean;
  /**
   * Resolve ambiguous and unknown tip states (`N` and IUPAC codes such as `R`) to the most likely inferred state.
   *
   * Gaps are left as deletions, because they are inferred structure, not missing data. Changes that involve ambiguous
   * characters on terminal branches then disappear from the branch mutations. Only defined for marginal
   * reconstruction; a no-op with a warning under `--method-anc=parsimony`.
   */
  impute_missing_data?: boolean;
  /**
   * Folder that receives the default outputs of the command
   *
   * Writes the default outputs of the command as `<dir>/<command>.<ext>`. `--output-selection` restricts the outputs
   * that the folder receives. The per-file flags (`--output-*`) override or supplement the files of the folder.
   *
   * An output that the run has no data for is skipped without a message, for example the substitution model of a run
   * that fits none. A per-file flag for such an output fails.
   *
   * Every output path follows these rules. A path that ends in `.gz`, `.bz2`, `.xz`, or `.zst` writes a compressed
   * file. The compression level is 2, unless the environment variable `GZ_COMPRESSION`, `BZ2_COMPRESSION`,
   * `XZ_COMPRESSION`, or `ZST_COMPRESSION` sets another level. `.gz`, `.xz`, and `.zst` compress with all `--jobs`
   * threads. `.bz2` compresses with one thread and is much slower to write and to read than the other formats. The
   * path `-` of a per-file flag writes the output uncompressed to standard output. Missing parent folders are
   * created.
   *
   * Table outputs choose the delimiter by the extension of their path: `.tsv` writes tabs and `.csv` commas, also
   * before a compression suffix (`dates.tsv.gz`); `-` writes tabs to standard output. Default names use `.tsv`.
   *
   * With several `--alignment` files, the outputs that carry sequence positions are written once per file:
   * reconstructed sequences, the augur node data of `ancestral`, Auspice, UShER MAT, Nexus, and Newick with
   * `--newick-annotations` other than `plain`. Files are numbered 1, 2, ... in the order of the `--alignment` list.
   * Their default names carry the number after the command name (`<dir>/<command>.1.<ext>`), and the file name of a
   * per-file flag for such an output must contain `{alignment}`, which is replaced by the number. Other tree outputs
   * with `{alignment}` in their file name are also written once per file.
   *
   * The outputs written once per CDS, such as the reconstructed amino-acid sequences, take the placeholder `{cds}`
   * or `%GENE` in the file name of their per-file flag, which is replaced by the name of the CDS. The placeholder is
   * required when more than one CDS is reconstructed; folder names are used as given.
   */
  output_all?: string;
  /**
   * Node comments of the Newick outputs: `plain`, `beast`, or `nhx`.
   *
   * `plain` writes no comments. `beast` writes a comment such as
   * `[&mutations="A45G,G136T",date=2016.45]` after each node, and `nhx` writes the same values as
   * `[&&NHX:key=value]`. The comments hold the mutations on the branch above the node, its date,
   * and its inferred trait value, as far as the command infers them. Nexus outputs always carry
   * `beast` comments, which FigTree reads.
   */
  newick_annotations?: NewickAnnotationsArg;
  /**
   * Path to output Newick tree file.
   *
   * `--newick-annotations` sets the node comments.
   */
  output_tree_nwk?: string;
  /**
   * Path to output Nexus tree file.
   *
   * The nodes carry BEAST comments (`[&mutations="A45G,G136T",date=2016.45]`).
   */
  output_tree_nexus?: string;
  /**
   * Path to output Auspice v2 JSON tree file.
   */
  output_tree_auspice?: string;
  /**
   * Path to output UShER MAT protobuf tree file.
   */
  output_tree_mat_pb?: string;
  /**
   * Path to output UShER MAT JSON tree file.
   */
  output_tree_mat_json?: string;
  /**
   * Path to output internal graph JSON tree file.
   */
  output_tree_graph_json?: string;
  /**
   * Path to output Graphviz DOT tree file.
   */
  output_tree_dot?: string;
  /**
   * List of outputs to produce with `--output-all`.
   *
   * Restricts which outputs `--output-all` writes. Special value `all` expands to every output available for this
   * command. Requires `--output-all`. Per-file flags are always honored regardless of this selection.
   *
   * A selected output that the run has no data for is skipped without a message, for example the substitution
   * model of a run that fits none. A per-file flag for such an output fails. An output that the settings rule
   * out fails in both forms, for example the sequences of `timetree --branch-length-mode input`.
   */
  output_selection?: Array<TimetreeOutputSelection>;
  /**
   * Disable indel (insertion and deletion) contributions to branch-length optimization and branch-length
   * distributions.
   *
   * When set, branch-length optimization uses the substitution-only likelihood, and the branch distributions of the
   * time inference exclude the Poisson indel term. This matches standard phylogenetic tools (RAxML, IQ-TREE, PhyML,
   * BEAST) and TreeTime 0.x. By default, indels count.
   */
  no_indels?: boolean;
  /**
   * Units of the divergence values in the augur node data and Auspice outputs.
   *
   * `mutations-per-site` (default): branch divergence as substitutions per site. `mutations`: count of reconstructed
   * substitutions per branch that change the state: gaps, `N`, and ambiguity codes compatible with the parent state
   * do not count. `mutations` requires reconstructed sequences, so it does not work with input branch lengths
   * (`--branch-length-mode=input`).
   */
  divergence_units?: DivergenceUnits;
  /**
   * Path to output augur-compatible node data JSON.
   *
   * Contains per-node dates, branch lengths, clock model parameters, confidence intervals, and divergence metrics. The
   * output is compatible with augur export v2 --node-data for Nextstrain pipeline integration.
   */
  output_node_data?: string;
  /**
   * Path to output the fitted substitution models as JSON.
   */
  output_model?: string;
  /**
   * Path to output the nucleotide sequences of the nodes as FASTA.
   *
   * Holds the reconstructed sequences of the internal nodes, and of the tips with `--include-leaves` or
   * `--reconstruct-tip-states`; `--impute-missing-data` resolves ambiguous tip states.
   */
  output_sequences?: string;
  /**
   * Path to output clock model JSON.
   */
  output_clock_model?: string;
  /**
   * Path to output the root-to-tip regression table.
   *
   * One row per sample: the date the regression used, the root-to-tip distance it regressed on, the date the clock
   * model predicts from that distance, and whether the clock filter excluded the sample.
   */
  output_rtt?: string;
  /**
   * Path to output node dates TSV: calendar date and numeric date of every node, with the bounds of the 90% max
   * posterior region with `--confidence`.
   */
  output_dates?: string;
  /**
   * Path to output the convergence values of every iteration as a table
   */
  output_tracelog?: string;
  /**
   * Path to output the coalescent time scale as a table (one row per skyline segment).
   *
   * Written when a coalescent prior is set with `--coalescent`. A fixed time scale writes one band-less segment over
   * the tree span.
   */
  output_coalescent?: string;
  /**
   * Path to output the coalescent time scale as a rich JSON document (inputs + segments).
   *
   * Written when a coalescent model is set.
   */
  output_coalescent_json?: string;
  /**
   * Report every state whose posterior probability is at most this far below the probability of the most likely
   * state.
   *
   * The value is a difference of probabilities from 0 to 1. With 0, the report names only the states that tie with
   * the most likely state. RAxML-NG uses 0.5 divided by the number of states, for example 0.125 for nucleotides.
   * The report is off when the value is not set.
   *
   * The reconstructed FASTA writes a position with more than one reported state as the IUPAC code of these states, or `N` for all four nucleotides. Internal nodes have a report at every position, leaves only at the positions that `--impute-missing-data` imputes.
   */
  ambiguity_threshold?: number;
  /**
   * List of the outputs that carry the ambiguity report.
   *
   * Without this list, every output of the run that can carry the report carries it. Requires
   * `--ambiguity-threshold`.
   */
  ambiguity_outputs?: Array<TimetreeAmbiguityOutput>;
  /**
   * Canonical topology ordering preset.
   */
  topology_order?: TopologyOrderArg;
  /**
   * Tree whose leaf order sets the target order
   *
   * Used by `--topology-order target-order` and `target-order-reverse`. Without this flag and `--topology-order-list`,
   * the leaf order of the input tree is the target order. A path that ends in `.gz`, `.bz2`, `.xz`, or `.zst` reads a
   * compressed file.
   */
  topology_order_tree?: string;
  /**
   * File with leaf names in the target order, one name per line
   *
   * Used by `--topology-order target-order` and `target-order-reverse`. Without this flag and `--topology-order-tree`,
   * the leaf order of the input tree is the target order. A path that ends in `.gz`, `.bz2`, `.xz`, or `.zst` reads a
   * compressed file.
   */
  topology_order_list?: string;
  /**
   * Aggregate used to map a subtree to a target-order position.
   */
  topology_order_aggregate?: TopologyOrderTargetAggregateArg;
  /**
   * Random seed
   *
   * Without a seed, a run with a random step draws one and logs it, so the run can be reproduced.
   */
  seed?: number;
};

export type ClockOutputSelection = 'all' | 'nwk' | 'nexus' | 'auspice' | 'mat-pb' | 'mat-json' | 'graph-json' | 'dot' | 'clock-model' | 'rtt' | 'rtt-chart';

/**
 * Fit a molecular clock by root-to-tip regression, and reroot the tree for the best clock signal
 */
export type ClockConfig = {
  /**
   * Tree in Newick format
   *
   * A path that ends in `.gz`, `.bz2`, `.xz`, or `.zst` reads a compressed file.
   */
  tree?: string;
  /**
   * Newick dialect of the tree inputs (the tree and the reference topology)
   *
   * A dialect is a tree structure and an annotation convention, written as `<structure>,<annotations>`. The
   * structure is classic (plain labels and branch lengths), enewick (hybrid nodes such as `x#H1`) or rich (eNewick
   * with support and probability fields). The annotations are plain (comments are text), beast (`[&key=value]`), nhx
   * (`[&&NHX:key=value]`) or mrbayes (`[&B name value]`). For example, `enewick,beast` reads networks with BEAST
   * annotations and `classic,nhx` reads NHX trees. TreeTime reads trees only, so a network input is an error.
   */
  newick_dialect?: 'classic,plain' | 'classic,beast' | 'classic,nhx' | 'classic,mrbayes' | 'enewick,plain' | 'enewick,beast' | 'enewick,nhx' | 'enewick,mrbayes' | 'rich,plain' | 'rich,beast' | 'rich,nhx' | 'rich,mrbayes';
  /**
   * Metadata table (CSV or TSV) with one row per sample
   *
   * `--metadata-id-columns` names the column that links a row to a tree tip. The other columns hold the data of the
   * sample, such as its sampling date or its traits. A path that ends in `.gz`, `.bz2`, `.xz`, or `.zst` reads a
   * compressed file.
   */
  metadata?: string;
  /**
   * Candidate column name(s) holding the taxon identifier that links metadata to tree tips
   *
   * The first listed column that is present in the header is used. Matching is case-insensitive.
   */
  metadata_id_columns?: Array<string>;
  /**
   * Candidate field delimiter(s) for the metadata table
   *
   * The delimiter actually present in the file is used. Defaults to comma, tab, and semicolon.
   */
  metadata_delimiters?: Array<string>;
  /**
   * Label of the column to be used as sampling date (auto-detected when omitted)
   */
  date_column?: string;
  /**
   * Format used to parse string sampling dates (numeric, ISO, and uncertain dates parse regardless)
   */
  date_format?: string;
  /**
   * Ignore tips that do not follow a loose clock: the number of interquartile ranges from the root-to-tip regression
   * beyond which a tip is an outlier.
   *
   * 0 switches the filter off.
   */
  clock_filter?: number;
  /**
   * Allow negative clock rates.
   *
   * By default, rates are forced to be positive. For trees with little temporal signal, removing this restriction
   * gives essentially mid-point rooting.
   */
  allow_negative_rate?: boolean;
  /**
   * Remove the tips that the clock filter flags from the tree.
   *
   * The clock filter flags a tip and leaves it in the tree by default. With this flag, the run removes the flagged tips
   * after the filter: timetree before the time inference, and clock before the final clock fit. Every output leaves the
   * removed tips out, and a run warning names them. The tips that --keep-tips and --keep-tips-file name stay in the
   * tree, flagged. Requires the clock filter (--clock-filter above 0).
   *
   * augur refine with a clock filter (--clock-filter-iqd) removes the flagged tips and also the tips without a usable
   * date. To remove the same tips, add --prune-undated-tips.
   */
  prune_filtered_tips?: boolean;
  /**
   * Remove the tips without a usable date from the tree.
   *
   * A tip has no usable date when the metadata gives no date for it, or a value that is not a date, a numeric date, or
   * a date range. Such a tip stays in the tree by default: timetree infers its date from the tree, and the clock fit
   * leaves it out. With this flag, the run removes these tips: timetree before the time inference, and clock before
   * the final clock fit. Every output leaves the removed tips out, and a run warning names them. The tips that
   * --keep-tips and --keep-tips-file name stay in the tree.
   *
   * Together with --prune-filtered-tips, the run removes the same tips as augur refine with a clock filter
   * (--clock-filter-iqd).
   */
  prune_undated_tips?: boolean;
  /**
   * Names of tips that stay in the tree when --prune-filtered-tips or --prune-undated-tips removes tips
   *
   * Accepts several names, separated by commas or spaces. A kept flagged tip stays flagged: the clock fit leaves it
   * out, and timetree dates it from the tree, as it dates a kept tip without a usable date. Names that match no tip are
   * ignored.
   */
  keep_tips?: Array<string>;
  /**
   * File with names of tips that stay in the tree when --prune-filtered-tips or --prune-undated-tips removes tips, one
   * name per line
   *
   * Surrounding whitespace is trimmed and empty lines are ignored. Names that match no tip are ignored, so the file
   * can list samples of several datasets. A path that ends in `.gz`, `.bz2`, `.xz`, or `.zst` reads a compressed file.
   * Use `-` to read uncompressed input from standard input (stdin).
   */
  keep_tips_file?: string;
  /**
   * Method that chooses the root of the tree
   *
   * `least-squares` and `oldest` use the sampling dates; `min-dev` and `midpoint` use only the branch lengths, root
   * once on the input branch lengths, and count every tip. Without a rooting setting the tree is rerooted by
   * least-squares. Use --outgroup to root on named tips, or --keep-root to keep the input root.
   */
  reroot?: RerootMethod;
  /**
   * Root the tree on the branch above the most recent common ancestor of the named tips
   *
   * With one tip, the root is placed on the branch leading to that tip.
   */
  outgroup?: Array<string>;
  /**
   * Keep the root of the input tree instead of rerooting it.
   */
  keep_root?: boolean;
  /**
   * Folder that receives the default outputs of the command
   *
   * Writes the default outputs of the command as `<dir>/<command>.<ext>`. `--output-selection` restricts the outputs
   * that the folder receives. The per-file flags (`--output-*`) override or supplement the files of the folder.
   *
   * An output that the run has no data for is skipped without a message, for example the substitution model of a run
   * that fits none. A per-file flag for such an output fails.
   *
   * Every output path follows these rules. A path that ends in `.gz`, `.bz2`, `.xz`, or `.zst` writes a compressed
   * file. The compression level is 2, unless the environment variable `GZ_COMPRESSION`, `BZ2_COMPRESSION`,
   * `XZ_COMPRESSION`, or `ZST_COMPRESSION` sets another level. `.gz`, `.xz`, and `.zst` compress with all `--jobs`
   * threads. `.bz2` compresses with one thread and is much slower to write and to read than the other formats. The
   * path `-` of a per-file flag writes the output uncompressed to standard output. Missing parent folders are
   * created.
   *
   * Table outputs choose the delimiter by the extension of their path: `.tsv` writes tabs and `.csv` commas, also
   * before a compression suffix (`dates.tsv.gz`); `-` writes tabs to standard output. Default names use `.tsv`.
   *
   * With several `--alignment` files, the outputs that carry sequence positions are written once per file:
   * reconstructed sequences, the augur node data of `ancestral`, Auspice, UShER MAT, Nexus, and Newick with
   * `--newick-annotations` other than `plain`. Files are numbered 1, 2, ... in the order of the `--alignment` list.
   * Their default names carry the number after the command name (`<dir>/<command>.1.<ext>`), and the file name of a
   * per-file flag for such an output must contain `{alignment}`, which is replaced by the number. Other tree outputs
   * with `{alignment}` in their file name are also written once per file.
   *
   * The outputs written once per CDS, such as the reconstructed amino-acid sequences, take the placeholder `{cds}`
   * or `%GENE` in the file name of their per-file flag, which is replaced by the name of the CDS. The placeholder is
   * required when more than one CDS is reconstructed; folder names are used as given.
   */
  output_all?: string;
  /**
   * Node comments of the Newick outputs: `plain`, `beast`, or `nhx`.
   *
   * `plain` writes no comments. `beast` writes a comment such as
   * `[&mutations="A45G,G136T",date=2016.45]` after each node, and `nhx` writes the same values as
   * `[&&NHX:key=value]`. The comments hold the mutations on the branch above the node, its date,
   * and its inferred trait value, as far as the command infers them. Nexus outputs always carry
   * `beast` comments, which FigTree reads.
   */
  newick_annotations?: NewickAnnotationsArg;
  /**
   * Path to output Newick tree file.
   *
   * `--newick-annotations` sets the node comments.
   */
  output_tree_nwk?: string;
  /**
   * Path to output Nexus tree file.
   *
   * The nodes carry BEAST comments (`[&mutations="A45G,G136T",date=2016.45]`).
   */
  output_tree_nexus?: string;
  /**
   * Path to output Auspice v2 JSON tree file.
   */
  output_tree_auspice?: string;
  /**
   * Path to output UShER MAT protobuf tree file.
   */
  output_tree_mat_pb?: string;
  /**
   * Path to output UShER MAT JSON tree file.
   */
  output_tree_mat_json?: string;
  /**
   * Path to output internal graph JSON tree file.
   */
  output_tree_graph_json?: string;
  /**
   * Path to output Graphviz DOT tree file.
   */
  output_tree_dot?: string;
  /**
   * List of outputs to produce with `--output-all`.
   *
   * Restricts which outputs `--output-all` writes. Special value `all` expands to every output available for this
   * command. Requires `--output-all`. Per-file flags are always honored regardless of this selection.
   *
   * A selected output that the run has no data for is skipped without a message, for example the substitution
   * model of a run that fits none. A per-file flag for such an output fails. An output that the settings rule
   * out fails in both forms, for example the sequences of `timetree --branch-length-mode input`.
   */
  output_selection?: Array<ClockOutputSelection>;
  /**
   * Path to output clock model JSON.
   */
  output_clock_model?: string;
  /**
   * Path to output the root-to-tip regression table.
   *
   * One row per sample: the date the regression used, the root-to-tip distance it regressed on, the date the clock
   * model predicts from that distance, and whether the clock filter excluded the sample.
   */
  output_rtt?: string;
  /**
   * Path to output the root-to-tip regression chart.
   *
   * The chart plots the root-to-tip divergence of each dated sample against its date, with the least-squares fit, its extrapolation to the root, and the samples that the clock filter excluded. It states the clock rate, the root date and R² of the fit. The extension chooses the image format: `.svg`, `.png` or `.pdf`.
   */
  output_rtt_chart?: string;
  /**
   * Canonical topology ordering preset.
   */
  topology_order?: TopologyOrderArg;
  /**
   * Tree whose leaf order sets the target order
   *
   * Used by `--topology-order target-order` and `target-order-reverse`. Without this flag and `--topology-order-list`,
   * the leaf order of the input tree is the target order. A path that ends in `.gz`, `.bz2`, `.xz`, or `.zst` reads a
   * compressed file.
   */
  topology_order_tree?: string;
  /**
   * File with leaf names in the target order, one name per line
   *
   * Used by `--topology-order target-order` and `target-order-reverse`. Without this flag and `--topology-order-tree`,
   * the leaf order of the input tree is the target order. A path that ends in `.gz`, `.bz2`, `.xz`, or `.zst` reads a
   * compressed file.
   */
  topology_order_list?: string;
  /**
   * Aggregate used to map a subtree to a target-order position.
   */
  topology_order_aggregate?: TopologyOrderTargetAggregateArg;
};

/**
 * Amino-acid substitution model: the values of `--model` that suit an amino-acid alphabet.
 *
 * The default `infer`, as in augur, infers a GTR model over the amino acids and the stop codon, starting from JC69.
 * Empirical matrices apply only when selected.
 */
export type AaModelName = 'infer' | 'jtt92';

export type MethodAncestral = 'marginal' | 'parsimony';

export type SampleMode = 'argmax' | 'root' | 'all';

export type AncestralOutputSelection = 'all' | 'nwk' | 'nexus' | 'auspice' | 'mat-pb' | 'mat-json' | 'graph-json' | 'dot' | 'node-data' | 'model' | 'sequences' | 'translations';

export type AncestralAmbiguityOutput = 'sequences' | 'translations' | 'node-data';

/**
 * Reconstruct ancestral sequences and map the mutations to the branches of a tree
 */
export type AncestralConfig = {
  /**
   * Aligned FASTA input
   *
   * Each `--alignment` file is numbered by its position in the list (1, 2, ...) and is one partition, unless
   * `--partition` entries of `ancestral`, `optimize`, or `timetree` split it into several. A path that ends in `.gz`,
   * `.bz2`, `.xz`, or `.zst` reads a compressed file. Use `-` to read uncompressed input from standard input (stdin);
   * `-` may appear at most once.
   */
  alignment?: Array<string>;
  /**
   * One partition: a set of sites of one `--alignment` file with its own substitution model; repeat the flag for each
   * partition
   *
   * Without `--partition`, each `--alignment` file is one partition with the model of `--model`. An entry is a YAML
   * or JSON map with the keys `name` (the name of the partition in outputs and messages), `alignment` (the number of
   * its `--alignment` file, 1, 2, ...; required with two or more files), `sites` (a list of site ranges, numbered
   * from 1: `a`, `a-b`, or `a-b\k` for every k-th site from a to b), `model` (the substitution model, default `infer`)
   * and `model_params` (the `key=value` items of `--model-params` for that model). Each entry carries its own model,
   * so `--model` and `--model-params` cannot be used together with `--partition`. Every alignment needs at least one
   * entry, and every site belongs to exactly one entry. An entry without `sites` takes the sites that the other entries
   * of its alignment leave; one entry per alignment can leave out `sites`. Write site ranges in single quotes or
   * without quotes, because YAML reads a backslash in double quotes as an escape. Example: `--partition "{name: cp1,
   * sites: ['101-1600\3']}" --partition "{name: cp2, sites: ['102-1600\3']}" --partition "{name: cp3, sites:
   * ['103-1600\3'], model: hky85, model_params: ['kappa=4']}" --partition "{name: noncoding}"`.
   */
  partition?: Array<PartitionSpec>;
  /**
   * Tree in Newick format
   *
   * A path that ends in `.gz`, `.bz2`, `.xz`, or `.zst` reads a compressed file.
   */
  tree?: string;
  /**
   * Newick dialect of the tree inputs (the tree and the reference topology)
   *
   * A dialect is a tree structure and an annotation convention, written as `<structure>,<annotations>`. The
   * structure is classic (plain labels and branch lengths), enewick (hybrid nodes such as `x#H1`) or rich (eNewick
   * with support and probability fields). The annotations are plain (comments are text), beast (`[&key=value]`), nhx
   * (`[&&NHX:key=value]`) or mrbayes (`[&B name value]`). For example, `enewick,beast` reads networks with BEAST
   * annotations and `classic,nhx` reads NHX trees. TreeTime reads trees only, so a network input is an error.
   */
  newick_dialect?: 'classic,plain' | 'classic,beast' | 'classic,nhx' | 'classic,mrbayes' | 'enewick,plain' | 'enewick,beast' | 'enewick,nhx' | 'enewick,mrbayes' | 'rich,plain' | 'rich,beast' | 'rich,nhx' | 'rich,mrbayes';
  /**
   * Treat tree tips that have no sequence in the alignment as fully ambiguous (missing data) instead of aborting.
   *
   * Without this flag the run aborts when more than one third of the tips lack a sequence, because the alignment may
   * not belong to the tree. Useful for per-CDS translations, where some samples have no peptide for a given CDS.
   */
  allow_missing_sequences?: boolean;
  /**
   * Alphabet of the sequences
   *
   * `nuc` (default): nucleotides A, C, G and T, with the IUPAC ambiguity codes and `N` for an unknown base. `aa`: the
   * 20 amino acids and the stop codon `*` as a 21st state, with `X` for an unknown residue. `aa-no-stop`: the 20
   * amino acids without a state for the stop codon.
   */
  alphabet?: AlphabetName;
  /**
   * Report sequence positions counted from 0 instead of 1.
   *
   * Applies to the mutations in the comments of Newick and Nexus trees and to the positions of the homoplasy
   * report. Auspice JSON, augur node data, and UShER MAT outputs count from 1, as their formats require. An input
   * table with positions, such as `--drms`, is always counted from 1.
   */
  zero_based?: boolean;
  /**
   * Genome annotation (GFF3) with the coordinates of the CDSs, for the annotations of the augur node data
   *
   * Also supplies the CDSs to reconstruct when `--cds-selection` is not given. A path that ends in `.gz`, `.bz2`,
   * `.xz`, or `.zst` reads a compressed file.
   */
  annotation?: string;
  /**
   * Path template of the amino-acid alignments, one FASTA file per CDS
   *
   * The template must contain a CDS placeholder, which is replaced by each name of `--cds-selection`, or by each CDS
   * of `--annotation` without `--cds-selection`. The placeholder is `{cds}` or `%GENE`.
   * A path that ends in `.gz`, `.bz2`, `.xz`, or `.zst` reads a compressed file.
   */
  translations?: string;
  /**
   * Names of the CDSs to reconstruct from `--translations`
   *
   * Without this setting, the run reconstructs every CDS of `--annotation`.
   */
  cds_selection?: Array<string>;
  /**
   * Substitution model to use
   *
   * `infer` infers a model from the data of each partition; each `--alignment` file is one partition. Alternatively,
   * name the model type. If the named model takes parameters, use `--model-params` to set them. The model applies to
   * every file. In commands with `--partition`, each entry carries its own model, so `--model` is an error next to
   * entries.
   */
  model?: GtrModelName;
  /**
   * Parameters for the model selected by `--model`, given as space-separated `key=value` items
   *
   * The parameters apply to the model of every partition; each `--alignment` file is one partition. In commands
   * with `--partition`, each entry carries its own model and parameters, so `--model-params` is an error next to
   * entries. Keys: `mu` (the overall substitution rate, every named model), `kappa` (the transition to transversion
   * ratio of `k80`, `hky85` and `t92`), `kappa1` and `kappa2` (the rate ratios of `tn93`), `pi` (the equilibrium
   * frequencies of `f81`, `hky85` and `tn93`: comma-separated numbers, one frequency per state of the alphabet in its
   * order, for example A, C, G and T for nucleotides, normalized to sum 1; also `pis`, `Pi`, `Pis`) and `pi_GC` (the
   * GC content of `t92`, between 0 and 1). A key left out keeps its default. Example: `--model hky85 --model-params
   * kappa=0.2 pis=0.25,0.25,0.25,0.25`.
   */
  model_params?: Array<string>;
  /**
   * Substitution model of the amino-acid sequences, as `--model` for the nucleotides
   *
   * The default `infer`, as in augur, infers the model from the data of each CDS.
   */
  aa_model?: AaModelName;
  /**
   * Method used for reconstructing ancestral sequences, which places the mutations on the branches
   */
  method_anc?: MethodAncestral;
  /**
   * Representation of the sequences on the tree
   *
   * The dense representation stores the probabilities of every state at every alignment position of each node; the
   * sparse representation stores only the variable positions. Dense is more accurate when branches are long and many
   * sites change, but uses more memory.
   */
  representation?: Representation;
  /**
   * How to pick ancestral states from the marginal posterior profile.
   *
   * 'argmax': most likely state at every node (deterministic, default).
   * 'root': sample from the posterior at the root only, argmax elsewhere (as augur's `sample_from_profile='root'`).
   * 'all': sample from the posterior at every node.
   *
   * Only affects marginal reconstruction (`--method-anc=marginal`). Use `--seed` for reproducible draws.
   */
  sample_from_profile?: SampleMode;
  /**
   * How to handle the gap characters of the input sequences
   *
   * `only-terminal` (default, as in TreeTime 0.x): replace the leading and trailing gaps of each sequence with the
   * unknown character of the alphabet (`N` or `X`). `all`: replace every gap with the unknown character. `none`: keep
   * every gap.
   */
  gap_fill?: GapFill;
  /**
   * Emit reconstructed leaf (tip) sequences in addition to internal nodes.
   */
  include_leaves?: boolean;
  /**
   * Same as `--include-leaves --impute-missing-data`: emit tip sequences with ambiguous and unknown states resolved to
   * the most likely inferred state.
   */
  reconstruct_tip_states?: boolean;
  /**
   * Include branch mutations from or to the fully ambiguous state (`N` for nucleotides, `X` for amino acids).
   *
   * By default these mutations are omitted from the branch mutations of the Newick and Nexus annotations, the Auspice
   * JSON, and the `muts` and `aa_muts` lists of augur node data. Other ambiguity codes, such as `K` or `R`, are always
   * reported. The flag does not affect the MAT outputs, which store `N` as missing data and never contain these
   * mutations.
   */
  report_ambiguous?: boolean;
  /**
   * Resolve ambiguous and unknown tip states (`N` and IUPAC codes such as `R`) to the most likely inferred state.
   *
   * Gaps are left as deletions, because they are inferred structure, not missing data. Changes that involve ambiguous
   * characters on terminal branches then disappear from the branch mutations. Only defined for marginal
   * reconstruction; a no-op with a warning under `--method-anc=parsimony`.
   */
  impute_missing_data?: boolean;
  /**
   * FASTA file with one amino-acid reference sequence of the root per CDS
   *
   * The root `aa_muts` of augur node data list the differences between this reference and the inferred root, and
   * always omit `X` and gaps. A path that ends in `.gz`, `.bz2`, `.xz`, or `.zst` reads a compressed file.
   */
  aa_root_sequence?: string;
  /**
   * Folder that receives the default outputs of the command
   *
   * Writes the default outputs of the command as `<dir>/<command>.<ext>`. `--output-selection` restricts the outputs
   * that the folder receives. The per-file flags (`--output-*`) override or supplement the files of the folder.
   *
   * An output that the run has no data for is skipped without a message, for example the substitution model of a run
   * that fits none. A per-file flag for such an output fails.
   *
   * Every output path follows these rules. A path that ends in `.gz`, `.bz2`, `.xz`, or `.zst` writes a compressed
   * file. The compression level is 2, unless the environment variable `GZ_COMPRESSION`, `BZ2_COMPRESSION`,
   * `XZ_COMPRESSION`, or `ZST_COMPRESSION` sets another level. `.gz`, `.xz`, and `.zst` compress with all `--jobs`
   * threads. `.bz2` compresses with one thread and is much slower to write and to read than the other formats. The
   * path `-` of a per-file flag writes the output uncompressed to standard output. Missing parent folders are
   * created.
   *
   * Table outputs choose the delimiter by the extension of their path: `.tsv` writes tabs and `.csv` commas, also
   * before a compression suffix (`dates.tsv.gz`); `-` writes tabs to standard output. Default names use `.tsv`.
   *
   * With several `--alignment` files, the outputs that carry sequence positions are written once per file:
   * reconstructed sequences, the augur node data of `ancestral`, Auspice, UShER MAT, Nexus, and Newick with
   * `--newick-annotations` other than `plain`. Files are numbered 1, 2, ... in the order of the `--alignment` list.
   * Their default names carry the number after the command name (`<dir>/<command>.1.<ext>`), and the file name of a
   * per-file flag for such an output must contain `{alignment}`, which is replaced by the number. Other tree outputs
   * with `{alignment}` in their file name are also written once per file.
   *
   * The outputs written once per CDS, such as the reconstructed amino-acid sequences, take the placeholder `{cds}`
   * or `%GENE` in the file name of their per-file flag, which is replaced by the name of the CDS. The placeholder is
   * required when more than one CDS is reconstructed; folder names are used as given.
   */
  output_all?: string;
  /**
   * Node comments of the Newick outputs: `plain`, `beast`, or `nhx`.
   *
   * `plain` writes no comments. `beast` writes a comment such as
   * `[&mutations="A45G,G136T",date=2016.45]` after each node, and `nhx` writes the same values as
   * `[&&NHX:key=value]`. The comments hold the mutations on the branch above the node, its date,
   * and its inferred trait value, as far as the command infers them. Nexus outputs always carry
   * `beast` comments, which FigTree reads.
   */
  newick_annotations?: NewickAnnotationsArg;
  /**
   * Path to output Newick tree file.
   *
   * `--newick-annotations` sets the node comments.
   */
  output_tree_nwk?: string;
  /**
   * Path to output Nexus tree file.
   *
   * The nodes carry BEAST comments (`[&mutations="A45G,G136T",date=2016.45]`).
   */
  output_tree_nexus?: string;
  /**
   * Path to output Auspice v2 JSON tree file.
   */
  output_tree_auspice?: string;
  /**
   * Path to output UShER MAT protobuf tree file.
   */
  output_tree_mat_pb?: string;
  /**
   * Path to output UShER MAT JSON tree file.
   */
  output_tree_mat_json?: string;
  /**
   * Path to output internal graph JSON tree file.
   */
  output_tree_graph_json?: string;
  /**
   * Path to output Graphviz DOT tree file.
   */
  output_tree_dot?: string;
  /**
   * List of outputs to produce with `--output-all`.
   *
   * Restricts which outputs `--output-all` writes. Special value `all` expands to every output available for this
   * command. Requires `--output-all`. Per-file flags are always honored regardless of this selection.
   *
   * A selected output that the run has no data for is skipped without a message, for example the substitution
   * model of a run that fits none. A per-file flag for such an output fails. An output that the settings rule
   * out fails in both forms, for example the sequences of `timetree --branch-length-mode input`.
   */
  output_selection?: Array<AncestralOutputSelection>;
  /**
   * Path to output augur-compatible node data JSON.
   *
   * Contains per-node nucleotide mutations, reconstructed sequences, the alignment mask, genome annotations, and the
   * reference (root) sequence. The output is compatible with augur export v2 --node-data for Nextstrain pipeline
   * integration.
   */
  output_node_data?: string;
  /**
   * Path to output the fitted substitution models as JSON.
   */
  output_model?: string;
  /**
   * Path to output the nucleotide sequences of the nodes as FASTA.
   *
   * Holds the reconstructed sequences of the internal nodes, and of the tips with `--include-leaves` or
   * `--reconstruct-tip-states`; `--impute-missing-data` resolves ambiguous tip states.
   */
  output_sequences?: string;
  /**
   * Path to output the amino-acid sequences of the nodes as FASTA, one file per CDS
   *
   * Holds the reconstructed sequence of every node, internal nodes included.
   */
  output_translations?: string;
  /**
   * Report every state whose posterior probability is at most this far below the probability of the most likely
   * state.
   *
   * The value is a difference of probabilities from 0 to 1. With 0, the report names only the states that tie with
   * the most likely state. RAxML-NG uses 0.5 divided by the number of states, for example 0.125 for nucleotides.
   * The report is off when the value is not set.
   *
   * A sequence output writes a position with more than one reported state as the ambiguity code of these states: an IUPAC code for nucleotides, `B`, `Z`, or `J` for amino acids, otherwise `N` or `X`. Internal nodes have a report at every position, leaves only at the positions that `--impute-missing-data` imputes. Nodes whose sequence `--sample-from-profile` draws have no report. The setting applies only when a marginal reconstruction runs (`--method-anc marginal`, or the amino-acid reconstruction of `--translations`), because Fitch parsimony computes no posterior.
   */
  ambiguity_threshold?: number;
  /**
   * List of the outputs that carry the ambiguity report.
   *
   * Without this list, every output of the run that can carry the report carries it. Requires
   * `--ambiguity-threshold`.
   */
  ambiguity_outputs?: Array<AncestralAmbiguityOutput>;
  /**
   * Canonical topology ordering preset.
   */
  topology_order?: TopologyOrderArg;
  /**
   * Tree whose leaf order sets the target order
   *
   * Used by `--topology-order target-order` and `target-order-reverse`. Without this flag and `--topology-order-list`,
   * the leaf order of the input tree is the target order. A path that ends in `.gz`, `.bz2`, `.xz`, or `.zst` reads a
   * compressed file.
   */
  topology_order_tree?: string;
  /**
   * File with leaf names in the target order, one name per line
   *
   * Used by `--topology-order target-order` and `target-order-reverse`. Without this flag and `--topology-order-tree`,
   * the leaf order of the input tree is the target order. A path that ends in `.gz`, `.bz2`, `.xz`, or `.zst` reads a
   * compressed file.
   */
  topology_order_list?: string;
  /**
   * Aggregate used to map a subtree to a target-order position.
   */
  topology_order_aggregate?: TopologyOrderTargetAggregateArg;
  /**
   * Random seed
   *
   * Without a seed, a run with a random step draws one and logs it, so the run can be reproduced.
   */
  seed?: number;
};

/**
 * Reroot methods available in the optimize command.
 *
 * Only date-free methods are valid here because optimize has no sampling dates.
 * Date-dependent methods (least-squares, oldest) are available
 * in the timetree and clock commands.
 */
export type OptimizeRerootMethod = 'min-dev' | 'midpoint';

/**
 * Initial branch lengths: input lengths, or estimates from the number of substitutions divided by the effective
 * alignment length. Valid input lengths can give Newton-Raphson a better starting point.
 */
export type InitialGuessMode = 'auto' | 'always' | 'never';

/**
 * Per-edge branch length optimization method.
 *
 * Controls how the maximum-likelihood branch length of each edge is found:
 * Optimizer of each branch length: Brent's method or Newton-Raphson, both on sqrt(t).
 */
export type BranchOptMethod = 'brent' | 'newton';

export type OptimizeOutputSelection = 'all' | 'nwk' | 'nexus' | 'auspice' | 'mat-pb' | 'mat-json' | 'graph-json' | 'dot' | 'node-data' | 'model';

/**
 * Optimize the branch lengths of a tree for the likelihood of an alignment
 */
export type OptimizeConfig = {
  /**
   * Aligned FASTA input
   *
   * Each `--alignment` file is numbered by its position in the list (1, 2, ...) and is one partition, unless
   * `--partition` entries of `ancestral`, `optimize`, or `timetree` split it into several. A path that ends in `.gz`,
   * `.bz2`, `.xz`, or `.zst` reads a compressed file. Use `-` to read uncompressed input from standard input (stdin);
   * `-` may appear at most once.
   */
  alignment?: Array<string>;
  /**
   * One partition: a set of sites of one `--alignment` file with its own substitution model; repeat the flag for each
   * partition
   *
   * Without `--partition`, each `--alignment` file is one partition with the model of `--model`. An entry is a YAML
   * or JSON map with the keys `name` (the name of the partition in outputs and messages), `alignment` (the number of
   * its `--alignment` file, 1, 2, ...; required with two or more files), `sites` (a list of site ranges, numbered
   * from 1: `a`, `a-b`, or `a-b\k` for every k-th site from a to b), `model` (the substitution model, default `infer`)
   * and `model_params` (the `key=value` items of `--model-params` for that model). Each entry carries its own model,
   * so `--model` and `--model-params` cannot be used together with `--partition`. Every alignment needs at least one
   * entry, and every site belongs to exactly one entry. An entry without `sites` takes the sites that the other entries
   * of its alignment leave; one entry per alignment can leave out `sites`. Write site ranges in single quotes or
   * without quotes, because YAML reads a backslash in double quotes as an escape. Example: `--partition "{name: cp1,
   * sites: ['101-1600\3']}" --partition "{name: cp2, sites: ['102-1600\3']}" --partition "{name: cp3, sites:
   * ['103-1600\3'], model: hky85, model_params: ['kappa=4']}" --partition "{name: noncoding}"`.
   */
  partition?: Array<PartitionSpec>;
  /**
   * Tree in Newick format
   *
   * A path that ends in `.gz`, `.bz2`, `.xz`, or `.zst` reads a compressed file.
   */
  tree?: string;
  /**
   * Newick dialect of the tree inputs (the tree and the reference topology)
   *
   * A dialect is a tree structure and an annotation convention, written as `<structure>,<annotations>`. The
   * structure is classic (plain labels and branch lengths), enewick (hybrid nodes such as `x#H1`) or rich (eNewick
   * with support and probability fields). The annotations are plain (comments are text), beast (`[&key=value]`), nhx
   * (`[&&NHX:key=value]`) or mrbayes (`[&B name value]`). For example, `enewick,beast` reads networks with BEAST
   * annotations and `classic,nhx` reads NHX trees. TreeTime reads trees only, so a network input is an error.
   */
  newick_dialect?: 'classic,plain' | 'classic,beast' | 'classic,nhx' | 'classic,mrbayes' | 'enewick,plain' | 'enewick,beast' | 'enewick,nhx' | 'enewick,mrbayes' | 'rich,plain' | 'rich,beast' | 'rich,nhx' | 'rich,mrbayes';
  /**
   * Treat tree tips that have no sequence in the alignment as fully ambiguous (missing data) instead of aborting.
   *
   * Without this flag the run aborts when more than one third of the tips lack a sequence, because the alignment may
   * not belong to the tree. Useful for per-CDS translations, where some samples have no peptide for a given CDS.
   */
  allow_missing_sequences?: boolean;
  /**
   * Alphabet of the sequences
   *
   * `nuc` (default): nucleotides A, C, G and T, with the IUPAC ambiguity codes and `N` for an unknown base. `aa`: the
   * 20 amino acids and the stop codon `*` as a 21st state, with `X` for an unknown residue. `aa-no-stop`: the 20
   * amino acids without a state for the stop codon.
   */
  alphabet?: AlphabetName;
  /**
   * Report sequence positions counted from 0 instead of 1.
   *
   * Applies to the mutations in the comments of Newick and Nexus trees and to the positions of the homoplasy
   * report. Auspice JSON, augur node data, and UShER MAT outputs count from 1, as their formats require. An input
   * table with positions, such as `--drms`, is always counted from 1.
   */
  zero_based?: boolean;
  /**
   * Method that chooses the root of the tree from the branch lengths
   *
   * The tree is rerooted once, on the branch lengths after the initial guess, and every tip counts. Without this
   * setting, the input root stays. The rerooting methods that need dates (`least-squares`, `oldest`) are available
   * where the inputs have dates.
   */
  reroot?: OptimizeRerootMethod;
  /**
   * Root the tree on the branch above the most recent common ancestor of the named tips
   *
   * With one tip, the root is placed on the branch leading to that tip.
   */
  outgroup?: Array<string>;
  /**
   * Keep the root of the input tree instead of rerooting it.
   */
  keep_root?: boolean;
  /**
   * Maximum number of iterations of the inference loop
   *
   * Polytomy resolution and coalescent models of the time inference need at least 2 iterations.
   */
  max_iter?: number;
  /**
   * Convergence threshold of the log-likelihood
   *
   * The loop stops when successive log-likelihoods differ by less than this value, or when it detects a 2-cycle with
   * an amplitude below this value.
   */
  tolerance?: number;
  /**
   * Damping of the branch length updates of the loop, from 0 (inclusive) to 1 (exclusive)
   *
   * Iteration i updates each branch length b to `b = b_new * (1 - d) + b_old * d`, with
   * `d = max(damping^(i+1), 0.01)`. Higher values reduce oscillation; 0 switches damping off.
   */
  damping?: number;
  /**
   * Initial branch lengths before the optimization of each branch
   */
  initial_branch_lengths?: InitialGuessMode;
  /**
   * Optimizer of each branch length; both methods optimize sqrt(t) in place of the branch length t
   */
  optimizer?: BranchOptMethod;
  /**
   * Disable collapsing of short internal branches.
   *
   * By default the optimize loop contracts every internal edge whose optimized length is zero,
   * unless an indel on the edge enters the likelihood and needs a positive length. After the
   * loop, internal edges shorter than 0.1/L (L is the number of sites of all alignments) with no
   * substitution in the marginal reconstruction are contracted too. The substitutions and indels
   * of a contracted edge move to its child edges, and the nodes it joined become one polytomy.
   * When set, such edges are kept in the output tree.
   */
  no_collapse_short_branches?: boolean;
  /**
   * Disable merging of polytomy siblings that share substitutions.
   *
   * By default, sibling branches in a polytomy that carry identical substitutions are grouped
   * under a new internal node. The step and the flag apply only to the sparse representation.
   */
  no_merge_shared_mutations?: boolean;
  /**
   * Disable the reversion hoist in polytomies.
   *
   * By default, when a child branch carries the exact reversion of a substitution on the node's
   * parent branch, a new node is inserted that groups the node with that child, removing one
   * mutation per reverted position. When set, those reversions are left in place. The step and the flag apply
   * only to the sparse representation.
   */
  no_hoist_reversions?: boolean;
  /**
   * Substitution model to use
   *
   * `infer` infers a model from the data of each partition; each `--alignment` file is one partition. Alternatively,
   * name the model type. If the named model takes parameters, use `--model-params` to set them. The model applies to
   * every file. In commands with `--partition`, each entry carries its own model, so `--model` is an error next to
   * entries.
   */
  model?: GtrModelName;
  /**
   * Parameters for the model selected by `--model`, given as space-separated `key=value` items
   *
   * The parameters apply to the model of every partition; each `--alignment` file is one partition. In commands
   * with `--partition`, each entry carries its own model and parameters, so `--model-params` is an error next to
   * entries. Keys: `mu` (the overall substitution rate, every named model), `kappa` (the transition to transversion
   * ratio of `k80`, `hky85` and `t92`), `kappa1` and `kappa2` (the rate ratios of `tn93`), `pi` (the equilibrium
   * frequencies of `f81`, `hky85` and `tn93`: comma-separated numbers, one frequency per state of the alphabet in its
   * order, for example A, C, G and T for nucleotides, normalized to sum 1; also `pis`, `Pi`, `Pis`) and `pi_GC` (the
   * GC content of `t92`, between 0 and 1). A key left out keeps its default. Example: `--model hky85 --model-params
   * kappa=0.2 pis=0.25,0.25,0.25,0.25`.
   */
  model_params?: Array<string>;
  /**
   * Relative substitution rates of the partitions
   *
   * Each `--alignment` file is one partition, or each `--partition` entry when there are entries. With two or more
   * partitions, all partitions share the branch lengths, and each partition has one relative rate that scales them for
   * the sites of that partition. `estimate` fits the rate of each partition with the rest of its substitution model
   * fixed (a partition with `--model infer` starts from its fitted rate), then divides all rates by their mean
   * weighted by the number of sites of each partition, so that this mean is 1. The branch lengths are then expected
   * substitutions per site, averaged over all sites of all partitions. `equal` fixes the rate of every partition at 1.
   *
   * The setting applies only with two or more partitions.
   */
  partition_rates?: PartitionRates;
  /**
   * Representation of the sequences on the tree
   *
   * The dense representation stores the probabilities of every state at every alignment position of each node; the
   * sparse representation stores only the variable positions. Dense is more accurate when branches are long and many
   * sites change, but uses more memory.
   */
  representation?: Representation;
  /**
   * How to handle the gap characters of the input sequences
   *
   * `only-terminal` (default, as in TreeTime 0.x): replace the leading and trailing gaps of each sequence with the
   * unknown character of the alphabet (`N` or `X`). `all`: replace every gap with the unknown character. `none`: keep
   * every gap.
   */
  gap_fill?: GapFill;
  /**
   * Folder that receives the default outputs of the command
   *
   * Writes the default outputs of the command as `<dir>/<command>.<ext>`. `--output-selection` restricts the outputs
   * that the folder receives. The per-file flags (`--output-*`) override or supplement the files of the folder.
   *
   * An output that the run has no data for is skipped without a message, for example the substitution model of a run
   * that fits none. A per-file flag for such an output fails.
   *
   * Every output path follows these rules. A path that ends in `.gz`, `.bz2`, `.xz`, or `.zst` writes a compressed
   * file. The compression level is 2, unless the environment variable `GZ_COMPRESSION`, `BZ2_COMPRESSION`,
   * `XZ_COMPRESSION`, or `ZST_COMPRESSION` sets another level. `.gz`, `.xz`, and `.zst` compress with all `--jobs`
   * threads. `.bz2` compresses with one thread and is much slower to write and to read than the other formats. The
   * path `-` of a per-file flag writes the output uncompressed to standard output. Missing parent folders are
   * created.
   *
   * Table outputs choose the delimiter by the extension of their path: `.tsv` writes tabs and `.csv` commas, also
   * before a compression suffix (`dates.tsv.gz`); `-` writes tabs to standard output. Default names use `.tsv`.
   *
   * With several `--alignment` files, the outputs that carry sequence positions are written once per file:
   * reconstructed sequences, the augur node data of `ancestral`, Auspice, UShER MAT, Nexus, and Newick with
   * `--newick-annotations` other than `plain`. Files are numbered 1, 2, ... in the order of the `--alignment` list.
   * Their default names carry the number after the command name (`<dir>/<command>.1.<ext>`), and the file name of a
   * per-file flag for such an output must contain `{alignment}`, which is replaced by the number. Other tree outputs
   * with `{alignment}` in their file name are also written once per file.
   *
   * The outputs written once per CDS, such as the reconstructed amino-acid sequences, take the placeholder `{cds}`
   * or `%GENE` in the file name of their per-file flag, which is replaced by the name of the CDS. The placeholder is
   * required when more than one CDS is reconstructed; folder names are used as given.
   */
  output_all?: string;
  /**
   * Node comments of the Newick outputs: `plain`, `beast`, or `nhx`.
   *
   * `plain` writes no comments. `beast` writes a comment such as
   * `[&mutations="A45G,G136T",date=2016.45]` after each node, and `nhx` writes the same values as
   * `[&&NHX:key=value]`. The comments hold the mutations on the branch above the node, its date,
   * and its inferred trait value, as far as the command infers them. Nexus outputs always carry
   * `beast` comments, which FigTree reads.
   */
  newick_annotations?: NewickAnnotationsArg;
  /**
   * Path to output Newick tree file.
   *
   * `--newick-annotations` sets the node comments.
   */
  output_tree_nwk?: string;
  /**
   * Path to output Nexus tree file.
   *
   * The nodes carry BEAST comments (`[&mutations="A45G,G136T",date=2016.45]`).
   */
  output_tree_nexus?: string;
  /**
   * Path to output Auspice v2 JSON tree file.
   */
  output_tree_auspice?: string;
  /**
   * Path to output UShER MAT protobuf tree file.
   */
  output_tree_mat_pb?: string;
  /**
   * Path to output UShER MAT JSON tree file.
   */
  output_tree_mat_json?: string;
  /**
   * Path to output internal graph JSON tree file.
   */
  output_tree_graph_json?: string;
  /**
   * Path to output Graphviz DOT tree file.
   */
  output_tree_dot?: string;
  /**
   * List of outputs to produce with `--output-all`.
   *
   * Restricts which outputs `--output-all` writes. Special value `all` expands to every output available for this
   * command. Requires `--output-all`. Per-file flags are always honored regardless of this selection.
   *
   * A selected output that the run has no data for is skipped without a message, for example the substitution
   * model of a run that fits none. A per-file flag for such an output fails. An output that the settings rule
   * out fails in both forms, for example the sequences of `timetree --branch-length-mode input`.
   */
  output_selection?: Array<OptimizeOutputSelection>;
  /**
   * Disable indel (insertion and deletion) contributions to branch-length optimization and branch-length
   * distributions.
   *
   * When set, branch-length optimization uses the substitution-only likelihood, and the branch distributions of the
   * time inference exclude the Poisson indel term. This matches standard phylogenetic tools (RAxML, IQ-TREE, PhyML,
   * BEAST) and TreeTime 0.x. By default, indels count.
   */
  no_indels?: boolean;
  /**
   * Units of the divergence values in the augur node data and Auspice outputs.
   *
   * `mutations-per-site` (default): branch divergence as substitutions per site. `mutations`: count of reconstructed
   * substitutions per branch that change the state: gaps, `N`, and ambiguity codes compatible with the parent state
   * do not count. `mutations` requires reconstructed sequences, so it does not work with input branch lengths
   * (`--branch-length-mode=input`).
   */
  divergence_units?: DivergenceUnits;
  /**
   * Path to output augur-compatible node data JSON.
   *
   * Contains per-node optimized branch lengths (divergence, substitutions per site) and the input alignment and tree
   * paths. The output is compatible with augur export v2 --node-data.
   */
  output_node_data?: string;
  /**
   * Path to output the fitted substitution models as JSON.
   */
  output_model?: string;
  /**
   * Canonical topology ordering preset.
   */
  topology_order?: TopologyOrderArg;
  /**
   * Tree whose leaf order sets the target order
   *
   * Used by `--topology-order target-order` and `target-order-reverse`. Without this flag and `--topology-order-list`,
   * the leaf order of the input tree is the target order. A path that ends in `.gz`, `.bz2`, `.xz`, or `.zst` reads a
   * compressed file.
   */
  topology_order_tree?: string;
  /**
   * File with leaf names in the target order, one name per line
   *
   * Used by `--topology-order target-order` and `target-order-reverse`. Without this flag and `--topology-order-tree`,
   * the leaf order of the input tree is the target order. A path that ends in `.gz`, `.bz2`, `.xz`, or `.zst` reads a
   * compressed file.
   */
  topology_order_list?: string;
  /**
   * Aggregate used to map a subtree to a target-order position.
   */
  topology_order_aggregate?: TopologyOrderTargetAggregateArg;
};

export type PruneOutputSelection = 'all' | 'nwk' | 'nexus' | 'auspice' | 'mat-pb' | 'mat-json' | 'graph-json' | 'dot';

/**
 * Collapse short branches and branches without mutations, and remove named nodes from a tree
 */
export type PruneConfig = {
  /**
   * Aligned FASTA input
   *
   * Each `--alignment` file is numbered by its position in the list (1, 2, ...) and is one partition, unless
   * `--partition` entries of `ancestral`, `optimize`, or `timetree` split it into several. A path that ends in `.gz`,
   * `.bz2`, `.xz`, or `.zst` reads a compressed file. Use `-` to read uncompressed input from standard input (stdin);
   * `-` may appear at most once.
   */
  alignment?: Array<string>;
  /**
   * Tree in Newick format
   *
   * A path that ends in `.gz`, `.bz2`, `.xz`, or `.zst` reads a compressed file.
   */
  tree?: string;
  /**
   * Newick dialect of the tree inputs (the tree and the reference topology)
   *
   * A dialect is a tree structure and an annotation convention, written as `<structure>,<annotations>`. The
   * structure is classic (plain labels and branch lengths), enewick (hybrid nodes such as `x#H1`) or rich (eNewick
   * with support and probability fields). The annotations are plain (comments are text), beast (`[&key=value]`), nhx
   * (`[&&NHX:key=value]`) or mrbayes (`[&B name value]`). For example, `enewick,beast` reads networks with BEAST
   * annotations and `classic,nhx` reads NHX trees. TreeTime reads trees only, so a network input is an error.
   */
  newick_dialect?: 'classic,plain' | 'classic,beast' | 'classic,nhx' | 'classic,mrbayes' | 'enewick,plain' | 'enewick,beast' | 'enewick,nhx' | 'enewick,mrbayes' | 'rich,plain' | 'rich,beast' | 'rich,nhx' | 'rich,mrbayes';
  /**
   * Treat tree tips that have no sequence in the alignment as fully ambiguous (missing data) instead of aborting.
   *
   * Without this flag the run aborts when more than one third of the tips lack a sequence, because the alignment may
   * not belong to the tree. Useful for per-CDS translations, where some samples have no peptide for a given CDS.
   */
  allow_missing_sequences?: boolean;
  /**
   * Alphabet of the sequences
   *
   * `nuc` (default): nucleotides A, C, G and T, with the IUPAC ambiguity codes and `N` for an unknown base. `aa`: the
   * 20 amino acids and the stop codon `*` as a 21st state, with `X` for an unknown residue. `aa-no-stop`: the 20
   * amino acids without a state for the stop codon.
   */
  alphabet?: AlphabetName;
  /**
   * Report sequence positions counted from 0 instead of 1.
   *
   * Applies to the mutations in the comments of Newick and Nexus trees and to the positions of the homoplasy
   * report. Auspice JSON, augur node data, and UShER MAT outputs count from 1, as their formats require. An input
   * table with positions, such as `--drms`, is always counted from 1.
   */
  zero_based?: boolean;
  /**
   * How to handle the gap characters of the input sequences
   *
   * `only-terminal` (default, as in TreeTime 0.x): replace the leading and trailing gaps of each sequence with the
   * unknown character of the alphabet (`N` or `X`). `all`: replace every gap with the unknown character. `none`: keep
   * every gap.
   */
  gap_fill?: GapFill;
  /**
   * Collapse branches shorter than this length
   *
   * Removes each internal branch with a length below LEN and attaches the children of its node to the parent node.
   */
  collapse_short?: number;
  /**
   * Collapse branches without mutations
   *
   * Removes each internal branch that has no mutation or other state transition mapped to it.
   *
   * Requires --alignment
   */
  collapse_empty?: boolean;
  /**
   * Merge branches in polytomies that share identical mutations
   *
   * When sibling branches in a polytomy (node with >2 children) carry identical substitutions,
   * they are grouped under a new internal node. The shared mutations move to the new branch
   * (parent to new node), and only unique mutations remain on children's edges.
   * Reduces tree builder artifacts from arbitrary binary resolution of polytomies.
   *
   * Requires --alignment
   */
  merge_shared_mutations?: boolean;
  /**
   * Names of nodes to remove from the tree
   *
   * Accepts several names, separated by commas or spaces.
   */
  remove?: Array<string>;
  /**
   * File with names of nodes to remove from the tree, one name per line
   *
   * Surrounding whitespace is trimmed and empty lines are ignored. A path that ends in `.gz`, `.bz2`, `.xz`, or `.zst`
   * reads a compressed file. Use `-` to read uncompressed input from standard input (stdin).
   */
  remove_file?: string;
  /**
   * Folder that receives the default outputs of the command
   *
   * Writes the default outputs of the command as `<dir>/<command>.<ext>`. `--output-selection` restricts the outputs
   * that the folder receives. The per-file flags (`--output-*`) override or supplement the files of the folder.
   *
   * An output that the run has no data for is skipped without a message, for example the substitution model of a run
   * that fits none. A per-file flag for such an output fails.
   *
   * Every output path follows these rules. A path that ends in `.gz`, `.bz2`, `.xz`, or `.zst` writes a compressed
   * file. The compression level is 2, unless the environment variable `GZ_COMPRESSION`, `BZ2_COMPRESSION`,
   * `XZ_COMPRESSION`, or `ZST_COMPRESSION` sets another level. `.gz`, `.xz`, and `.zst` compress with all `--jobs`
   * threads. `.bz2` compresses with one thread and is much slower to write and to read than the other formats. The
   * path `-` of a per-file flag writes the output uncompressed to standard output. Missing parent folders are
   * created.
   *
   * Table outputs choose the delimiter by the extension of their path: `.tsv` writes tabs and `.csv` commas, also
   * before a compression suffix (`dates.tsv.gz`); `-` writes tabs to standard output. Default names use `.tsv`.
   *
   * With several `--alignment` files, the outputs that carry sequence positions are written once per file:
   * reconstructed sequences, the augur node data of `ancestral`, Auspice, UShER MAT, Nexus, and Newick with
   * `--newick-annotations` other than `plain`. Files are numbered 1, 2, ... in the order of the `--alignment` list.
   * Their default names carry the number after the command name (`<dir>/<command>.1.<ext>`), and the file name of a
   * per-file flag for such an output must contain `{alignment}`, which is replaced by the number. Other tree outputs
   * with `{alignment}` in their file name are also written once per file.
   *
   * The outputs written once per CDS, such as the reconstructed amino-acid sequences, take the placeholder `{cds}`
   * or `%GENE` in the file name of their per-file flag, which is replaced by the name of the CDS. The placeholder is
   * required when more than one CDS is reconstructed; folder names are used as given.
   */
  output_all?: string;
  /**
   * Node comments of the Newick outputs: `plain`, `beast`, or `nhx`.
   *
   * `plain` writes no comments. `beast` writes a comment such as
   * `[&mutations="A45G,G136T",date=2016.45]` after each node, and `nhx` writes the same values as
   * `[&&NHX:key=value]`. The comments hold the mutations on the branch above the node, its date,
   * and its inferred trait value, as far as the command infers them. Nexus outputs always carry
   * `beast` comments, which FigTree reads.
   */
  newick_annotations?: NewickAnnotationsArg;
  /**
   * Path to output Newick tree file.
   *
   * `--newick-annotations` sets the node comments.
   */
  output_tree_nwk?: string;
  /**
   * Path to output Nexus tree file.
   *
   * The nodes carry BEAST comments (`[&mutations="A45G,G136T",date=2016.45]`).
   */
  output_tree_nexus?: string;
  /**
   * Path to output Auspice v2 JSON tree file.
   */
  output_tree_auspice?: string;
  /**
   * Path to output UShER MAT protobuf tree file.
   */
  output_tree_mat_pb?: string;
  /**
   * Path to output UShER MAT JSON tree file.
   */
  output_tree_mat_json?: string;
  /**
   * Path to output internal graph JSON tree file.
   */
  output_tree_graph_json?: string;
  /**
   * Path to output Graphviz DOT tree file.
   */
  output_tree_dot?: string;
  /**
   * List of outputs to produce with `--output-all`.
   *
   * Restricts which outputs `--output-all` writes. Special value `all` expands to every output available for this
   * command. Requires `--output-all`. Per-file flags are always honored regardless of this selection.
   *
   * A selected output that the run has no data for is skipped without a message, for example the substitution
   * model of a run that fits none. A per-file flag for such an output fails. An output that the settings rule
   * out fails in both forms, for example the sequences of `timetree --branch-length-mode input`.
   */
  output_selection?: Array<PruneOutputSelection>;
  /**
   * Canonical topology ordering preset.
   */
  topology_order?: TopologyOrderArg;
  /**
   * Tree whose leaf order sets the target order
   *
   * Used by `--topology-order target-order` and `target-order-reverse`. Without this flag and `--topology-order-list`,
   * the leaf order of the input tree is the target order. A path that ends in `.gz`, `.bz2`, `.xz`, or `.zst` reads a
   * compressed file.
   */
  topology_order_tree?: string;
  /**
   * File with leaf names in the target order, one name per line
   *
   * Used by `--topology-order target-order` and `target-order-reverse`. Without this flag and `--topology-order-tree`,
   * the leaf order of the input tree is the target order. A path that ends in `.gz`, `.bz2`, `.xz`, or `.zst` reads a
   * compressed file.
   */
  topology_order_list?: string;
  /**
   * Aggregate used to map a subtree to a target-order position.
   */
  topology_order_aggregate?: TopologyOrderTargetAggregateArg;
};

/**
 * The configuration is accepted.
 */
export type CheckConfigResponseValid = {
  /**
   * Command the configuration is for.
   */
  command: AppCommand;
  /**
   * The configuration with every default filled in and without output paths, which the app sets for each run.
   */
  config: SparseConfig;
  /**
   * The command line and the YAML config that reproduce the configuration.
   */
  code: ConfigCode;
  /**
   * Findings about the configuration and its input files.
   */
  checks: Array<RunCheck>;
  /**
   * The option of each choice of the command that the configuration selects.
   */
  choices: Array<ActiveChoice>;
  /**
   * The value the run uses for each setting that the configuration leaves at its default, as a short text.
   */
  effective: Array<EffectiveValue>;
  /**
   * Settings whose resolved values differ between the run of `run_id` (first) and the configuration (second), and
   * inputs whose file contents differ, in catalog order. The settings that the app sets for every run, the output
   * files and their paths, are not compared. Absent without `run_id`, and when the run executes another command.
   */
  run_differences?: Array<SettingDifference>;
  status: 'valid';
};

/**
 * The configuration is rejected.
 */
export type CheckConfigResponseInvalid = {
  /**
   * Command the configuration is for.
   */
  command: AppCommand;
  /**
   * The error, as the CLI prints it.
   */
  message: string;
  /**
   * The errors that caused `message`, outermost first.
   */
  causes: Array<string>;
  /**
   * Problems found by parsing and by the schema check, empty for other errors.
   */
  problems: Array<ConfigProblem>;
  /**
   * The problems drawn against the configuration text, when the text could be parsed.
   */
  rendered?: string;
  /**
   * The problems as a user reads them: each parse and schema problem with its help, or the error and its causes.
   */
  messages: Array<string>;
  /**
   * Findings about the configuration and its input files; the rejection is among them.
   */
  checks: Array<RunCheck>;
  /**
   * The option of each choice of the command that the configuration selects, when the configuration could be
   * merged over the defaults.
   */
  choices: Array<ActiveChoice>;
  /**
   * The value the run uses for each setting that the configuration leaves at its default, as a short text, when the
   * configuration could be merged over the defaults.
   */
  effective: Array<EffectiveValue>;
  status: 'invalid';
};

/**
 * A value that controls the analysis.
 */
export type SettingDifferenceSetting = {
  /**
   * Key path of the setting joined with `.`.
   */
  key: string;
  /**
   * Name of the setting, as the setting catalog labels it, for example `Coalescent prior`.
   */
  label: string;
  /**
   * Group of the setting, as the headings of `treetime <command> --help` name it, for example `Coalescent prior`.
   */
  group: string;
  /**
   * What the setting is for.
   */
  purpose: SettingPurpose;
  /**
   * Value in the first configuration; absent when it leaves the setting unset.
   */
  first?: JsonValue;
  /**
   * Value in the second configuration; absent when it leaves the setting unset.
   */
  second?: JsonValue;
  kind: 'setting';
};

/**
 * Input files with different contents.
 */
export type SettingDifferenceInput = {
  /**
   * Key path of the setting joined with `.`.
   */
  key: string;
  /**
   * Name of the setting, as the setting catalog labels it, for example `Coalescent prior`.
   */
  label: string;
  /**
   * Group of the setting, as the headings of `treetime <command> --help` name it, for example `Coalescent prior`.
   */
  group: string;
  /**
   * What the setting is for.
   */
  purpose: SettingPurpose;
  /**
   * Paths of the files of the first configuration.
   */
  first: Array<string>;
  /**
   * Paths of the files of the second configuration.
   */
  second: Array<string>;
  kind: 'input';
};

/**
 * The configuration is accepted.
 */
export type RunConfigResponseValid = {
  /**
   * The configuration as the run records it, with every default filled in, the outputs the run layer adds,
   * `output_all` set to `out`, and each uploaded input at its path in the run's folder, `inputs/<name>`.
   */
  config: SparseConfig;
  /**
   * The command line and the YAML config that reproduce the run.
   */
  code: ConfigCode;
  /**
   * Hash that a run of this configuration records, to find finished runs with the same settings and input
   * contents; absent when an input cannot be read.
   */
  config_hash?: string;
  /**
   * Why `config_hash` is absent.
   */
  config_hash_error?: string;
  status: 'valid';
};

/**
 * The configuration is rejected.
 */
export type RunConfigResponseInvalid = {
  /**
   * The error, as the CLI prints it.
   */
  message: string;
  /**
   * The errors that caused `message`, outermost first.
   */
  causes: Array<string>;
  /**
   * Problems found by parsing and by the schema check, empty for other errors.
   */
  problems: Array<ConfigProblem>;
  status: 'invalid';
};

/**
 * A number.
 */
export type StatisticValueNumber = {
  /**
   * The number.
   */
  value: number;
  kind: 'number';
};

/**
 * A date.
 */
export type StatisticValueDate = {
  /**
   * The date.
   */
  date: YearDate;
  kind: 'date';
};

export type RunRecordTimetree = {
  /**
   * Identifier of the run, also the name of its folder.
   */
  id: JobId;
  /**
   * Title shown in run lists. Until the user renames the run, the app names it after its dataset, its analysis, and
   * the analysis settings that differ from those of its source run, or from the defaults for a run without a source,
   * for example `ebola/100, time tree: skyline, confidence`; it names three changed settings and counts the others,
   * as in `+2`. A renamed run keeps its title.
   */
  title: string;
  /**
   * Whether the user renamed the run.
   */
  renamed: boolean;
  /**
   * Name of the example dataset whose files the run reads, for example `ebola/100`; absent for the user's own files.
   */
  example?: string;
  /**
   * State of the run.
   */
  status: RunStatus;
  /**
   * Whether the run is pinned in run lists.
   */
  pinned: boolean;
  /**
   * Run whose settings this run started from, such as the source of a variant. The source may have been deleted
   * since.
   */
  source_run_id?: JobId;
  /**
   * Group of related runs in the run history: the group of the source run, or for a run without a source, the group
   * of the earliest run with the same input contents, else the run's own id.
   */
  group_id: JobId;
  /**
   * Size of the run in bytes: its output files and the uploaded inputs that no other run references, as of the
   * last read of the record.
   */
  size: number;
  /**
   * Seed of the random number generator that the run used, for a run with a random step: the configured seed, or
   * the seed the run drew when the configuration sets none.
   */
  seed?: number;
  /**
   * Time the run was created.
   */
  created_at: string;
  /**
   * Time the computation started.
   */
  started_at?: string;
  /**
   * Time the run ended.
   */
  finished_at?: string;
  /**
   * Duration of the computation, in seconds.
   */
  duration_seconds?: number;
  /**
   * Version of TreeTime that ran the command.
   */
  treetime_version: string;
  /**
   * Input files the run read. Before the run starts, the uploaded inputs its configuration names.
   */
  inputs: Array<RunInput>;
  /**
   * Files uploaded for the run before it started; the run drops them when it starts.
   */
  uploads: Array<StoredInput>;
  /**
   * SHA-256 of the canonical resolved configuration, with each input path replaced by that input's SHA-256 and output
   * paths removed. Two runs with equal hashes used the same settings on the same input contents.
   */
  config_hash?: string;
  /**
   * Setting keys whose values differ from the command defaults, as dot-separated key paths.
   */
  changed_settings: Array<string>;
  /**
   * Key results of a finished run, for run lists.
   */
  headline: RunHeadline;
  /**
   * Files the run wrote, with paths relative to the run's `out/` folder.
   */
  output_files: Array<OutputFile>;
  /**
   * Warnings of the run, in the order raised. A run that failed keeps the warnings raised before the failure.
   */
  warnings: Array<RunWarning>;
  /**
   * The error of a failed run.
   */
  error?: RunError;
  config: TimetreeConfig;
  command: 'timetree';
};

